-- Massachusetts, all five batches. The state had two stops.
--
-- Eighty-nine categories arrived outside the enum, more than any state so far,
-- and most were compounds — cryptids-and-folklore, geology-and-folklore,
-- folklore-and-history. Compounds are filed under the more specific half:
-- somebody browsing cryptids wants the cryptid, and somebody browsing folklore
-- reaches it through the story anyway.
--
-- Two decisions in there worth naming. Anything ending in -history goes to
-- weird history, including communications-history and space-history, because a
-- claim about where the first telephone call happened is a claim about a
-- building. And odd-monuments parts company with monuments: a war memorial is
-- history, a memorial to a potato shed is a thing you pull over for.
--
-- 'open-grounds' appeared as an access value for the Metropolitan State
-- Hospital: grounds walkable, buildings not. Mapped to 'limited', which is
-- exactly that — you can go, but not everywhere.
--
-- The Salem entries cluster tightly because Essex Street is about two hundred
-- metres long and has a dozen attractions on it. Those are not duplicates.
--
-- 250 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Mapparium Globe', 'mapparium-globe', 'roadside-oddities', 42.34546, -71.08685, 'Boston', 'MA', 'A three-story stained-glass globe built in 1935 lets visitors walk through the center of a frozen-in-time world map. Because the political boundaries were never updated, countries such as Siam and the Soviet Union remain on the glass, while the sphere''s acoustics create a dramatic whispering-gallery effect.', 'limited', 'https://www.atlasobscura.com/places/mapparium', 'https://www.christianscience.com/find-us/visit-the-mother-church/mapparium', 'America/New_York', now()),
  ('Great Boston Molasses Flood Plaque', 'great-boston-molasses-flood-plaque', 'weird-history', 42.36834, -71.05585, 'Boston', 'MA', 'A small marker near the North End waterfront remembers the 1919 Great Molasses Flood, when a storage tank burst and a wave of molasses tore through the neighborhood, killing 21 people and injuring scores more. The understated plaque marks one of Boston''s strangest and deadliest industrial disasters.', 'open', 'https://www.atlasobscura.com/places/great-boston-molasses-flood-plaque', null, 'America/New_York', now()),
  ('The Ether Dome', 'the-ether-dome', 'weird-history', 42.36243, -71.06978, 'Boston', 'MA', 'Inside Massachusetts General Hospital is the historic operating theater where ether anesthesia was publicly demonstrated during surgery in 1846. The room also contains antique surgical material, a skeleton and an Egyptian mummy, making it one of Boston''s strongest medical-history oddities.', 'limited', 'https://www.atlasobscura.com/places/ether-dome', null, 'America/New_York', now()),
  ('Forest Hills Cemetery Miniature Village', 'forest-hills-cemetery-miniature-village', 'weird-history', 42.29487, -71.10566, 'Boston', 'MA', 'Hidden among the rocks and trees of Forest Hills Cemetery is a group of tiny stone buildings representing occupations such as architect, grocer, musician and poet. The miniature village is easy to miss inside the enormous Victorian cemetery and feels more like woodland folk art than a graveyard feature.', 'open', 'https://www.atlasobscura.com/places/forest-hills-cemetery', 'https://www.foresthillscemetery.com/', 'America/New_York', now()),
  ('Hood Milk Bottle', 'hood-milk-bottle', 'roadside-oddities', 42.35165, -71.05017, 'Boston', 'MA', 'A 40-foot wooden milk bottle stands beside the Boston Children''s Museum. Originally constructed in 1930 as a novelty ice-cream stand, it was later moved to Boston by ferry and remains one of the city''s clearest examples of giant-object roadside architecture.', 'open', 'https://www.atlasobscura.com/places/hood-milk-bottle', null, 'America/New_York', now()),
  ('World''s Largest Air-Insulated Van de Graaff Generator', 'worlds-largest-air-insulated-van-de-graaff-generator', 'roadside-oddities', 42.36762, -71.07073, 'Boston', 'MA', 'The Museum of Science operates an enormous Van de Graaff generator capable of producing spectacular indoor lightning. Built around machinery created by Robert Van de Graaff, the towering apparatus is used in live electricity demonstrations rather than sitting silently behind glass.', 'limited', 'https://www.atlasobscura.com/places/worlds-largest-airinsulated-van-de-graaff-generator', 'https://www.mos.org/visit/live-presentations/lightning', 'America/New_York', now()),
  ('Museum of Bad Art', 'museum-of-bad-art', 'museums', 42.3222, -71.06248, 'Boston', 'MA', 'The Museum of Bad Art deliberately collects artwork judged too strange, awkward or unsuccessful for conventional museums. Its current Boston gallery is inside Dorchester Brewing Company, where rotating selections from a collection of hundreds of pieces are displayed with deadpan curatorial interpretations.', 'open', 'https://museumofbadart.org/location/', 'https://museumofbadart.org/', 'America/New_York', now()),
  ('Edgar Allan Poe Square and Statue', 'edgar-allan-poe-square-and-statue', 'weird-history', 42.3523, -71.06731, 'Boston', 'MA', 'Near the vanished street where Edgar Allan Poe was born, Boston has installed a dramatic statue of the writer striding forward with a raven and a heart spilling from his suitcase. The surrounding plaza is officially named for Poe, despite his famously complicated relationship with his birth city.', 'open', 'https://www.atlasobscura.com/places/edgar-allan-poe-square', null, 'America/New_York', now()),
  ('King''s Chapel Crypt', 'kings-chapel-crypt', 'weird-history', 42.35806, -71.06001, 'Boston', 'MA', 'Twenty-one tombs lie beneath King''s Chapel, including the Strangers'' Tomb, which contains dozens of people who died in Boston without the means for private burial. Authorized Bell and Bones tours descend below the church into the historic crypt.', 'limited', 'https://www.atlasobscura.com/places/kings-chapel-crypt', 'https://www.kings-chapel.org/', 'America/New_York', now()),
  ('Tomb of the Mather Family', 'tomb-of-the-mather-family', 'haunted', 42.36738, -71.05551, 'Boston', 'MA', 'Increase Mather and his son Cotton Mather are buried together in Copp''s Hill Burying Ground. Cotton became deeply connected to colonial writings about witchcraft and defended the Salem witch trials in ''Wonders of the Invisible World,'' giving this otherwise modest brick tomb an unusually dark historical association.', 'open', 'https://www.atlasobscura.com/places/tomb-mather-family', null, 'America/New_York', now()),
  ('The Witch House', 'the-witch-house', 'weird-history', 42.52155, -70.8989, 'Salem', 'MA', 'The seventeenth-century home of Judge Jonathan Corwin is the only surviving building in Salem with direct ties to the 1692 witch trials. Corwin participated in the proceedings, and the preserved house now interprets the trials, colonial life and the beliefs that helped fuel the panic.', 'limited', 'https://www.atlasobscura.com/places/the-witch-house', 'https://www.thewitchhouse.org/', 'America/New_York', now()),
  ('Salem Witch Trials Memorial', 'salem-witch-trials-memorial', 'weird-history', 42.52038, -70.89157, 'Salem', 'MA', 'Twenty stone benches set into a quiet memorial courtyard bear the names and execution dates of the people killed during the Salem witch trials. Rather than turning the history into a Halloween attraction, the site functions as a restrained memorial beside the Old Burying Point.', 'open', 'https://www.atlasobscura.com/places/salem-witch-trials-memorial', null, 'America/New_York', now()),
  ('Proctor''s Ledge Memorial', 'proctors-ledge-memorial', 'weird-history', 42.51761, -70.90909, 'Salem', 'MA', 'Researchers identified Proctor''s Ledge as the location where 19 people accused of witchcraft were hanged in 1692. A small memorial now marks the execution site in a residential neighborhood; there is no dedicated parking, so visitors should approach quietly and respect nearby homes.', 'open', 'https://www.atlasobscura.com/places/proctors-ledge', null, 'America/New_York', now()),
  ('Witch Dungeon Museum', 'witch-dungeon-museum', 'haunted', 42.52257, -70.89719, 'Salem', 'MA', 'This long-running Salem attraction combines a live witch-trial reenactment with a basement recreation of the cramped conditions endured by accused prisoners. It is more theatrical than scholarly, but its aging wax figures and dungeon scenes make it a particularly OddWay version of Salem tourism.', 'limited', 'https://www.atlasobscura.com/places/witch-dungeon-museum', 'https://www.witchdungeon.com/', 'America/New_York', now()),
  ('Count Orlok''s Nightmare Gallery', 'count-orloks-nightmare-gallery', 'museums', 42.52142, -70.89485, 'Salem', 'MA', 'A horror and monster museum packed with life-size creatures, film props and highly detailed recreations of famous movie monsters. The gallery has moved within Salem over the years and is now on Essex Street, so older location pins should not be used.', 'limited', 'https://www.atlasobscura.com/places/count-orloks-nightmare-gallery', 'https://www.nightmaregallery.com/', 'America/New_York', now()),
  ('International Monster Museum', 'international-monster-museum', 'cryptids', 42.52224, -70.89314, 'Salem', 'MA', 'Visitors carry lanterns through a theatrical museum filled with werewolves, dragons, ghosts, cryptids and monsters drawn from folklore around the world. Created by special-effects artists, it sits inside Witch City Mall and leans fully into the creatures rather than Salem''s witch-trial history.', 'limited', 'https://www.internationalmonstermuseum.com/', 'https://www.internationalmonstermuseum.com/', 'America/New_York', now()),
  ('Real Pirates Salem', 'real-pirates-salem', 'weird-history', 42.51964, -70.89131, 'Salem', 'MA', 'Artifacts recovered from the wreck of the Whydah Gally tell the story of the pirate ship that sank off Cape Cod in 1717. Coins, weapons and other objects come from the only authenticated Golden Age pirate shipwreck discovered in North American waters.', 'limited', 'https://www.realpiratessalem.com/', 'https://www.realpiratessalem.com/', 'America/New_York', now()),
  ('Bewitched Statue', 'bewitched-statue', 'roadside-oddities', 42.52133, -70.89585, 'Salem', 'MA', 'A bronze Elizabeth Montgomery as Samantha Stephens sits astride a crescent moon in downtown Salem. The statue was installed as a promotional tribute to the television series ''Bewitched,'' which filmed several episodes in Salem, and its cheerful sitcom witch makes a strange contrast with the city''s real 1692 history.', 'open', 'https://www.roadsideamerica.com/story/16317', null, 'America/New_York', now()),
  ('Rebecca Nurse Homestead and Graveyard', 'rebecca-nurse-homestead-and-graveyard', 'weird-history', 42.55836, -70.9483, 'Danvers', 'MA', 'The preserved homestead of Rebecca Nurse includes a family graveyard where a monument stands over remains traditionally identified as hers. Nurse was executed for witchcraft in 1692 despite an initial not-guilty verdict, and another executed victim, George Jacobs Sr., was later reburied on the property.', 'limited', 'https://www.atlasobscura.com/places/rebecca-nurse-homestead-and-graveyard', 'https://www.rebeccanurse.org/', 'America/New_York', now()),
  ('Salem Village Parsonage Site', 'salem-village-parsonage-site', 'weird-history', 42.56593, -70.9625, 'Danvers', 'MA', 'Archaeological foundations mark the home of Reverend Samuel Parris, where Betty Parris and Abigail Williams began exhibiting the strange behavior that helped ignite the 1692 witchcraft crisis. The house is gone, but the exposed foundation makes the beginning of the panic physically routeable.', 'open', 'https://www.atlasobscura.com/places/salem-village-parsonage', null, 'America/New_York', now()),
  ('Lizzie Borden House', 'lizzie-borden-house', 'weird-history', 41.69881, -71.15641, 'Fall River', 'MA', 'The house where Andrew and Abby Borden were murdered with a hatchet in 1892 now operates as a museum and inn. Guests can tour the rooms connected with the killings — or sleep in the house overnight — while the still-unsolved identity of the murderer keeps the case alive more than a century later.', 'limited', 'https://lizzie-borden.com/', 'https://lizzie-borden.com/', 'America/New_York', now()),
  ('Lizzie Borden''s Grave', 'lizzie-bordens-grave', 'weird-history', 41.70766, -71.13827, 'Fall River', 'MA', 'Lizzie Borden is buried in Oak Grove Cemetery beside members of the same family whose murders made her infamous. Her own marker is unexpectedly small and simply reads ''Lizbeth''; painted arrows inside the cemetery guide visitors toward the Borden plot during open hours.', 'limited', 'https://www.roadsideamerica.com/story/50971', null, 'America/New_York', now()),
  ('Hockomock Swamp', 'hockomock-swamp', 'cryptids', 41.99463, -71.04157, 'West Bridgewater', 'MA', 'Massachusetts'' largest freshwater wetland sits at the center of the region popularly called the Bridgewater Triangle. Generations of stories describe strange lights, ghostly voices, Bigfoot-like creatures and enormous winged animals in and around the swamp; these are folklore and reported experiences, not established phenomena.', 'limited', 'https://www.atlasobscura.com/places/hockomock-swamp-massachusetts', null, 'America/New_York', now()),
  ('Freetown-Fall River State Forest', 'freetown-fall-river-state-forest', 'folklore', 41.77992, -71.04228, 'Assonet', 'MA', 'This large state forest forms another major point in Bridgewater Triangle lore. Stories attached to the woods include Pukwudgies, phantom lights and other unexplained encounters, while the forest also has a documented history of serious crimes. The paranormal material should be presented as regional folklore rather than fact.', 'open', 'https://newenglandhistoricalsociety.com/the-pukwudgies-of-the-bridgewater-triangle/', 'https://www.mass.gov/locations/freetown-fall-river-state-forest', 'America/New_York', now()),
  ('Dighton Rock Museum', 'dighton-rock-museum', 'folklore', 41.81288, -71.10643, 'Berkley', 'MA', 'A roughly 40-ton boulder covered with carved symbols has inspired competing theories involving Indigenous people, Norse explorers, Portuguese navigators and other proposed creators. The rock was removed from the riverbed and placed inside a small museum at Dighton Rock State Park for preservation.', 'limited', 'https://www.mass.gov/locations/dighton-rock-state-park', null, 'America/New_York', now()),
  ('King Philip''s Cave', 'king-philips-cave', 'folklore', 41.98045, -71.13037, 'Norton', 'MA', 'A secluded rock shelter is traditionally associated with Metacomet, the Wampanoag leader known to English colonists as King Philip, during the final weeks of King Philip''s War. Modern ghost stories have added phantom drums, voices and lights to the location''s much more serious historical significance.', 'limited', 'https://www.atlasobscura.com/places/king-philips-cave', null, 'America/New_York', now()),
  ('Dogtown and the Babson Boulder Trail', 'dogtown-and-the-babson-boulder-trail', 'weird-history', 42.63641, -70.66113, 'Gloucester', 'MA', 'The woods above Gloucester contain cellar holes from an abandoned colonial settlement known as Dogtown. Decades after the village vanished, millionaire Roger Babson had dozens of huge boulders carved with commands and maxims such as ''USE YOUR HEAD'' and ''GET A JOB,'' creating one of New England''s strangest hiking trails.', 'open', 'https://www.atlasobscura.com/places/dogtown-babson-words-rocks', null, 'America/New_York', now()),
  ('Hoosac Tunnel East Portal', 'hoosac-tunnel-east-portal', 'weird-history', 42.67552, -72.99843, 'Florida', 'MA', 'The nearly five-mile Hoosac Tunnel earned the nickname ''Bloody Pit'' during its brutal nineteenth-century construction, when roughly 200 workers died. Stories of apparitions and unexplained voices followed the disaster history. The tunnel remains an active railroad: view the portal only from a safe lawful area and never enter or walk the tracks.', 'roadside', 'https://www.atlasobscura.com/places/hoosac-tunnel', null, 'America/New_York', now()),
  ('Spider Gates Cemetery', 'spider-gates-cemetery', 'folklore', 42.26444, -71.90005, 'Leicester', 'MA', 'The small Friends Cemetery became infamous under the nickname Spider Gates because of its former decorative entrance and wild stories claiming it was an entrance to Hell. The cemetery itself is real, peaceful and open to respectful visitors, while the surrounding watershed property is posted against trespassing.', 'limited', 'https://www.atlasobscura.com/places/spider-gates-cemetery', null, 'America/New_York', now()),
  ('Rutland Prison Camp Ruins', 'rutland-prison-camp-ruins', 'weird-history', 42.40318, -72.0023, 'Rutland', 'MA', 'Concrete foundations, tunnels, root cellars and other remnants of an early twentieth-century prison farm are slowly disappearing into the woods. The complex once housed minor offenders and operated a large agricultural program before being abandoned in the 1930s; the ruins are now accessible on public recreation land.', 'open', 'https://www.atlasobscura.com/places/rutland-prison-camp', null, 'America/New_York', now()),
  ('Becket Historic Quarry and Forest', 'becket-historic-quarry-and-forest', 'weird-history', 42.25509, -73.01574, 'Becket', 'MA', 'An abandoned granite-quarry operation has been preserved as a public forest filled with old machinery sites, derrick remains, quarry pits and interpretive trails. Instead of clearing away the industrial past, the Becket Land Trust has left much of it in place as an outdoor museum.', 'open', 'https://housatonicheritage.org/Places/becket-historic-quarry-forest-becket-mass/', 'https://becketlandtrust.org/historic-quarry/', 'America/New_York', now()),
  ('Three Sisters Sanctuary', 'three-sisters-sanctuary', 'roadside-oddities', 42.47086, -72.80926, 'Goshen', 'MA', 'A private art environment has grown into acres of mosaics, stones, metal figures, towers, dragons, glass and gardens merging into the surrounding woodland. The handmade sanctuary is still evolving and is open to paying visitors during posted hours.', 'open', 'https://threesisterssanctuary.com/', 'https://threesisterssanctuary.com/', 'America/New_York', now()),
  ('The Paper House', 'the-paper-house', 'roadside-oddities', 42.67289, -70.63459, 'Rockport', 'MA', 'Mechanical engineer Elis Stenman built a summer house using layers of newspaper, glue and varnish instead of conventional wall material. He then continued the experiment by constructing newspaper furniture, including a desk, chairs and a piano covering. The seasonal attraction still operates on an old-fashioned honor system.', 'limited', 'https://www.roadsideamerica.com/story/2109', 'https://paperhouserockport.com/', 'America/New_York', now()),
  ('Hammond Castle Museum', 'hammond-castle-museum', 'roadside-oddities', 42.58521, -70.69276, 'Gloucester', 'MA', 'Inventor John Hays Hammond Jr. built a medieval-style seaside castle as his home, laboratory and showcase for antiquities. The eccentric structure mixes genuine old architectural fragments with twentieth-century technology, and current programming even explores Hammond''s experiments involving parapsychology and Spiritualism.', 'limited', 'https://hammondcastle.org/', 'https://hammondcastle.org/', 'America/New_York', now()),
  ('Dungeon Rock', 'dungeon-rock', 'haunted', 42.47505, -70.98611, 'Lynn', 'MA', 'Spiritualist Hiram Marble spent decades tunneling into a rock formation because he believed the ghost of pirate Thomas Veale was directing him toward buried treasure. Marble and his son died without finding it, but their narrow 135-foot excavation still exists in Lynn Woods and opens on a limited schedule.', 'limited', 'https://www.atlasobscura.com/places/dungeon-rock', null, 'America/New_York', now()),
  ('Bancroft Tower', 'bancroft-tower', 'roadside-oddities', 42.27551, -71.81734, 'Worcester', 'MA', 'A 56-foot miniature feudal castle rises from Salisbury Park as a memorial to historian and U.S. Navy secretary George Bancroft. The stone folly contains small rooms and battlements but was built mainly as an elaborate decorative monument; the grounds are normally open even when the tower interior is locked.', 'open', 'https://www.atlasobscura.com/places/bancroft-tower', null, 'America/New_York', now()),
  ('Dinosaur Footprints of Holyoke', 'dinosaur-footprints-of-holyoke', 'museums', 42.24169, -72.62341, 'Holyoke', 'MA', 'Hundreds of Early Jurassic dinosaur tracks are exposed in sandstone beside the Connecticut River. The three-toed prints were once thought to belong to giant birds and helped shape early American paleontology; the preserve is normally open from April through November.', 'limited', 'https://www.atlasobscura.com/places/dinosaur-footprints-holyoke', 'https://thetrustees.org/place/dinosaur-footprints/', 'America/New_York', now()),
  ('Eyrie House Ruins', 'eyrie-house-ruins', 'weird-history', 42.28015, -72.62048, 'Holyoke', 'MA', 'Stone walls and cellar holes are all that remain of a once-popular mountaintop hotel. The Eyrie House was destroyed in 1901 after owner William Street tried to cremate two dead horses on a funeral pyre and accidentally set the property ablaze.', 'open', 'https://www.atlasobscura.com/places/eyrie-house-ruins', null, 'America/New_York', now()),
  ('Acton Bigfoot at YV Art Museum', 'acton-bigfoot-at-yv-art-museum', 'cryptids', 42.51841, -71.41825, 'Acton', 'MA', 'A roughly 23-foot steel Bigfoot towers among the outdoor sculptures at YV Art Museum and Contemporary Arts International. Rather than pretending to document a sighting, the massive Sasquatch works as a piece of monumental cryptid art in an already unusual sculpture landscape.', 'limited', 'https://www.roadsideamerica.com/tip/81876', 'https://cai-yv.org/', 'America/New_York', now()),
  ('Bicentennial Chair', 'bicentennial-chair', 'roadside-oddities', 42.57603, -71.9839, 'Gardner', 'MA', 'Gardner''s history as ''Chair City'' produced a series of oversized chairs competing for world-record status. The surviving Bicentennial Chair was erected in 1976 and, although no longer the world''s largest, remains a giant monument to the city''s furniture-making past.', 'open', 'https://www.atlasobscura.com/places/bicentennial-chair', null, 'America/New_York', now()),
  ('Spud of Steel — Potato Head', 'spud-of-steel-potato-head', 'roadside-oddities', 42.02102, -71.49356, 'Bellingham', 'MA', 'A large Mr. Potato Head styled as a construction worker stands outside Hilltop Farms only a short distance from Rhode Island. The metal ''Spud of Steel'' is one of the few publicly displayed Potato Head statues surviving outside the toy''s home state.', 'roadside', 'https://www.roadsideamerica.com/tip/84008', null, 'America/New_York', now()),
  ('Witch Rock', 'witch-rock', 'folklore', 41.72628, -70.84029, 'Rochester', 'MA', 'A huge boulder in a residential front yard has a broom-riding witch painted across its face and carries generations of ghost stories involving voices, laughter and apparitions. The supernatural claims are folklore, and the rock is on private residential property, so it should only be viewed respectfully from the public roadside.', 'private', 'https://www.atlasobscura.com/places/witch-rock', null, 'America/New_York', now()),
  ('Thom Reed UFO Encounter Site', 'thom-reed-ufo-encounter-site', 'ufos', 42.12391, -73.3546, 'Sheffield', 'MA', 'A small area near the covered-bridge site commemorates Thom Reed''s claim that members of his family encountered a UFO here in 1969. The original granite monument became the subject of a local dispute and was removed, but the site remains associated with one of the Berkshires'' best-known UFO stories.', 'open', 'https://assets.atlasobscura.com/places/thom-reed-ufo-monument-park', null, 'America/New_York', now()),
  ('Uncle Sam Plaza', 'uncle-sam-plaza', 'weird-history', 42.41584, -71.1532, 'Arlington', 'MA', 'A bronze statue honors Arlington-born Samuel Wilson, the meatpacker traditionally associated with the origin of the national personification ''Uncle Sam.'' Whether the familiar story is completely accurate is debated, but Arlington has firmly embraced the connection with this dedicated plaza.', 'open', 'https://www.atlasobscura.com/places/uncle-sam-plaza', null, 'America/New_York', now()),
  ('La Salette International Crèche Museum', 'la-salette-international-cr-che-museum', 'museums', 41.93055, -71.26231, 'Attleboro', 'MA', 'More than 1,500 Nativity scenes from over 100 countries fill the International Crèche Museum at the National Shrine of Our Lady of La Salette. The enormous collection ranges across cultures and artistic styles, making a single biblical scene repeat in hundreds of dramatically different forms.', 'open', 'https://lasaletteattleboroshrine.org/museum', 'https://lasaletteattleboroshrine.org/museum', 'America/New_York', now()),
  ('Whydah Pirate Museum', 'whydah-pirate-museum', 'museums', 41.65004, -70.22501, 'West Yarmouth', 'MA', 'The museum displays treasure and artifacts recovered from the Whydah Gally, the pirate ship commanded by Samuel Bellamy that wrecked off Cape Cod in 1717. Its discovery produced the first authenticated pirate-ship wreck ever identified, giving the collection a much stronger historical basis than typical pirate attractions.', 'limited', 'https://www.discoverpirates.com/', 'https://www.discoverpirates.com/', 'America/New_York', now()),
  ('Edward Gorey House', 'edward-gorey-house', 'museums', 41.7054, -70.24252, 'Yarmouth Port', 'MA', 'The former home of illustrator Edward Gorey preserves the wonderfully macabre world behind his small, grim books and drawings. Exhibitions mix original art, personal objects and eccentric collections from an artist whose work was filled with mysterious deaths, ominous children and dark humor.', 'limited', 'https://www.edwardgoreyhouse.org/', 'https://www.edwardgoreyhouse.org/', 'America/New_York', now()),
  ('Blaschka Glass Flowers', 'blaschka-glass-flowers', 'museums', 42.37843, -71.11573, 'Cambridge', 'MA', 'Harvard''s famous Glass Flowers are thousands of astonishingly realistic plant models made almost entirely from glass by Leopold and Rudolf Blaschka. Their botanical accuracy is so convincing that visitors often struggle to believe the leaves, stems, blossoms and tiny anatomical details are glasswork.', 'limited', 'https://www.hmnh.harvard.edu/glass-flowers', 'https://www.hmnh.harvard.edu/', 'America/New_York', now()),
  ('O''Reilly Spite House', 'oreilly-spite-house', 'roadside-oddities', 42.38321, -71.13301, 'Cambridge', 'MA', 'After a neighboring landowner reportedly refused to buy his narrow parcel, Francis O''Reilly built an eight-foot-wide building on it in 1908 simply to make use of the strip and spite the neighbor. The tiny structure still stands and remains occupied, so it should be viewed only from the public sidewalk.', 'private', 'https://www.atlasobscura.com/places/o-reilly-spite-house', null, 'America/New_York', now()),
  ('Bancroft''s Castle', 'bancrofts-castle', 'weird-history', 42.60848, -71.55977, 'Groton', 'MA', 'Stone ruins on Gibbet Hill are all that remain of General William Bancroft''s ambitious early twentieth-century country estate. The unfinished structure later became a private club before burning, leaving castle-like walls that can now be reached by public hiking trails.', 'open', 'https://www.atlasobscura.com/places/bancroft-castle', null, 'America/New_York', now()),
  ('Phineas Gage Skull and Iron Rod', 'phineas-gage-skull-and-iron-rod', 'weird-history', 42.3352, -71.1038, 'Boston', 'MA', 'Harvard''s Warren Anatomical Museum preserves the skull of railroad foreman Phineas Gage along with the iron tamping rod that blasted through his head in an 1848 accident. Gage survived, and the case became one of the most famous episodes in the early history of neuroscience. The collection is housed at Harvard Medical School; check current public-access rules before visiting.', 'limited', 'https://www.atlasobscura.com/places/warren-anatomical-museum', null, 'America/New_York', now()),
  ('Easter Island Fisherman', 'easter-island-fisherman', 'roadside-oddities', 42.39374, -71.14122, 'Cambridge', 'MA', 'A giant fisherman statue stands outside the Royal Sonesta-area/Alewife corridor like a survivor from the classic fiberglass roadside era. The oversized figure has moved over the years, so older photos and maps may show him elsewhere; this pin reflects the currently documented Cambridge location.', 'roadside', 'https://www.roadsideamerica.com/location/ma', null, 'America/New_York', now()),
  ('MIT Museum', 'mit-museum', 'museums', 42.3623, -71.0868, 'Cambridge', 'MA', 'MIT''s museum turns experimental science and engineering into a public collection of robots, holography, kinetic art, early computing, artificial intelligence and prototypes. Its current home at the Gambrill Center in Kendall Square makes it one of the easiest places in Massachusetts to encounter genuinely strange technology.', 'open', 'https://mitmuseum.mit.edu/', 'https://mitmuseum.mit.edu/', 'America/New_York', now()),
  ('Great Brook Farm Robotic Milking Barn', 'great-brook-farm-robotic-milking-barn', 'roadside-oddities', 42.55583, -71.35333, 'Carlisle', 'MA', 'At a working dairy farm inside Great Brook Farm State Park, cows can use an automated robotic milking system largely on their own schedule. Visitors can see modern dairy technology operating inside a historic New England farm landscape; barn access and demonstrations vary by season and program.', 'limited', 'https://www.mass.gov/locations/great-brook-farm-state-park', 'https://www.mass.gov/locations/great-brook-farm-state-park', 'America/New_York', now()),
  ('Hail to the Sunrise', 'hail-to-the-sunrise', 'weird-history', 42.63998, -72.91287, 'Charlemont', 'MA', 'A bronze Native American figure faces east with outstretched arms beside the Mohawk Trail. Installed in 1932, the monument was created by the Improved Order of Red Men and reflects an older, non-Native fraternal interpretation of Indigenous imagery, making its history more complicated than the striking roadside silhouette suggests.', 'open', 'https://www.atlasobscura.com/places/hail-to-the-sunrise', null, 'America/New_York', now()),
  ('Grave of Grizzly Adams', 'grave-of-grizzly-adams', 'weird-history', 42.13127, -71.96878, 'Charlton', 'MA', 'John ''Grizzly'' Adams, the nineteenth-century mountain man and animal trainer, is buried beneath a monument topped by a carved bear. His traveling menageries and exaggerated frontier image helped turn him into a lasting American folk character.', 'open', 'https://www.atlasobscura.com/places/grave-of-grizzly-adams', null, 'America/New_York', now()),
  ('Clinton Train Tunnel', 'clinton-train-tunnel', 'weird-history', 42.40509, -71.68401, 'Clinton', 'MA', 'A disused railroad tunnel cuts beneath a wooded ridge near Clinton. The damp stone bore is a surviving remnant of nineteenth-century rail infrastructure and has the atmosphere of an abandoned underground passage; conditions and access can change, so follow current local rules and never enter if posted closed.', 'limited', 'https://www.atlasobscura.com/places/clinton-train-tunnel', null, 'America/New_York', now()),
  ('Authors'' Ridge', 'authors-ridge', 'weird-history', 42.46065, -71.34034, 'Concord', 'MA', 'A wooded corner of Sleepy Hollow Cemetery holds the graves of Ralph Waldo Emerson, Henry David Thoreau, Nathaniel Hawthorne, Louisa May Alcott and other members of Concord''s extraordinary literary circle. The concentration of famous writers makes the ridge feel like a compact cemetery of American literature.', 'open', 'https://www.atlasobscura.com/places/authors-ridge', null, 'America/New_York', now()),
  ('Endicott Pear Tree', 'endicott-pear-tree', 'museums', 42.54822, -70.93006, 'Danvers', 'MA', 'Traditionally dated to the 1630s, this ancient pear tree is often called the oldest cultivated fruit tree in North America. It has survived storms, vandalism and centuries of development and still produces fruit, although access is restricted because it stands on private corporate property.', 'limited', 'https://www.atlasobscura.com/places/endicott-pear-tree', null, 'America/New_York', now()),
  ('Salem Village Witchcraft Victims Memorial', 'salem-village-witchcraft-victims-memorial', 'weird-history', 42.56532, -70.9594, 'Danvers', 'MA', 'Unlike the better-known memorial in modern Salem, this monument stands in Danvers — the community that was Salem Village in 1692, where the crisis began. Stone panels commemorate the accused and preserve excerpts from their words, giving OddWay a second, geographically distinct witch-trial memorial tied directly to the village.', 'open', 'https://www.atlasobscura.com/places/salem-village-witchcraft-victims-memorial', null, 'America/New_York', now()),
  ('Pine Ridge Pet Cemetery', 'pine-ridge-pet-cemetery', 'weird-history', 42.26598, -71.18377, 'Dedham', 'MA', 'Founded in the nineteenth century, Pine Ridge is one of America''s oldest pet cemeteries. Thousands of animal graves include those of explorer Richard Byrd''s dog Igloo and several dogs once owned by Lizzie Borden, making the peaceful grounds unexpectedly rich in famous-animal history.', 'limited', 'https://www.atlasobscura.com/places/pine-ridge-pet-cemetery', null, 'America/New_York', now()),
  ('Fairbanks House', 'fairbanks-house', 'weird-history', 42.24323, -71.16776, 'Dedham', 'MA', 'Built around 1637–1641, the Fairbanks House is generally regarded as the oldest surviving timber-frame house in North America. Its irregular additions, low rooms and centuries of family occupation make it feel considerably stranger than a polished colonial reconstruction; tours are seasonal.', 'limited', 'https://www.fairbankshouse.org/', 'https://www.fairbankshouse.org/', 'America/New_York', now()),
  ('Scargo Tower', 'scargo-tower', 'roadside-oddities', 41.73944, -70.18021, 'Dennis', 'MA', 'A 30-foot cobblestone observation tower rises on Scargo Hill above Cape Cod. The present tower dates to 1901 and replaced two earlier structures, giving visitors a castle-like viewpoint over Scargo Lake and, on clear days, Cape Cod Bay.', 'open', 'https://www.dennishistsoc.org/scargo-tower', null, 'America/New_York', now()),
  ('12-Foot-Tall Pear', '12-foot-tall-pear', 'roadside-oddities', 42.31998, -71.06216, 'Boston', 'MA', 'An enormous bright-yellow pear stands outside a Dorchester property on Columbia Road. The oversized fruit is a classic giant-object roadside attraction: simple, unexplained at a glance, and almost impossible to miss once you know where to look.', 'roadside', 'https://www.roadsideamerica.com/location/ma', null, 'America/New_York', now()),
  ('Myles Standish Monument', 'myles-standish-monument', 'weird-history', 42.01391, -70.68217, 'Duxbury', 'MA', 'A 116-foot granite tower topped by a statue of Pilgrim military leader Myles Standish rises from a hill overlooking Duxbury. The unusually tall nineteenth-century monument looks like a stone watchtower and opens for interior climbing only on selected dates.', 'limited', 'https://www.mass.gov/locations/myles-standish-monument-state-reservation', null, 'America/New_York', now()),
  ('Doane Rock', 'doane-rock', 'roadside-oddities', 41.84426, -69.95777, 'Eastham', 'MA', 'A massive glacial erratic rests beside the road within Cape Cod National Seashore. The boulder was carried here by ice and left behind as the glaciers retreated, producing one of the Cape''s largest and easiest-to-reach pieces of Ice Age geology.', 'open', 'https://www.nps.gov/places/doane-rock.htm', null, 'America/New_York', now()),
  ('Three Sisters Lighthouses', 'three-sisters-lighthouses', 'roadside-oddities', 41.85947, -69.9571, 'Eastham', 'MA', 'Three small nineteenth-century lighthouse towers stand together in the woods after being retired and moved inland. Their original arrangement along the coast supposedly resembled three women in white dresses with black hats, earning them the nickname ''Three Sisters.''', 'open', 'https://www.nps.gov/caco/learn/historyculture/three-sisters-lighthouses.htm', null, 'America/New_York', now()),
  ('Selee Satanic Mill Marker', 'selee-satanic-mill-marker', 'folklore', 42.0483, -71.15688, 'Easton', 'MA', 'A historical marker identifies the site of an eighteenth-century sawmill linked by later folklore to owner Israel Selee, who was said to be a wizard assisted by Satanic imps. The mill history is real; the demonic workforce belongs firmly to local legend.', 'roadside', 'https://www.atlasobscura.com/places/selee-satanic-mill-marker', null, 'America/New_York', now()),
  ('Gravity Research Foundation Anti-Gravity Monument', 'gravity-research-foundation-anti-gravity-monument', 'roadside-oddities', 42.4069, -71.11915, 'Medford', 'MA', 'A monument at Tufts University recalls eccentric businessman Roger Babson''s Gravity Research Foundation, established partly from his desire to understand — and potentially defeat — gravity. Babson funded anti-gravity research monuments on college campuses across the country after blaming gravity for a family drowning.', 'open', 'https://www.hmdb.org/m.asp?m=108006', null, 'America/New_York', now()),
  ('Elizabeth Short — Black Dahlia Memorial', 'elizabeth-short-black-dahlia-memorial', 'weird-history', 42.41949, -71.10244, 'Medford', 'MA', 'A memorial in Medford Cemetery remembers Elizabeth Short, the Massachusetts-born woman whose 1947 murder in Los Angeles became known as the Black Dahlia case. Short is not buried here, but the marker gives her hometown region a physical connection to one of America''s most famous unsolved murders.', 'open', 'https://www.atlasobscura.com/places/elizabeth-short-memorial', null, 'America/New_York', now()),
  ('Jumbo the Elephant Statue', 'jumbo-the-elephant-statue', 'roadside-oddities', 42.40775, -71.12058, 'Medford', 'MA', 'A bronze Jumbo stands on the Tufts University campus honoring the enormous circus elephant that became the school''s mascot. After Jumbo died in an 1885 train collision, P.T. Barnum donated his hide to Tufts; the original specimen was destroyed by fire in 1975, leaving the statue as the campus''s most visible elephant memorial.', 'open', 'https://www.atlasobscura.com/places/jumbo-the-elephant', null, 'America/New_York', now()),
  ('Moby-Dick Whaleman''s Pulpit', 'moby-dick-whalemans-pulpit', 'weird-history', 41.6352, -70.92375, 'New Bedford', 'MA', 'Herman Melville described a ship''s-bow pulpit inside the Seamen''s Bethel in ''Moby-Dick,'' even though no such pulpit existed there at the time. After a movie adaptation built one, the church eventually installed a permanent version, allowing fiction to reshape the real place that inspired it.', 'open', 'https://www.atlasobscura.com/places/seamens-bethel', null, 'America/New_York', now()),
  ('Beer Can Museum', 'beer-can-museum', 'museums', 42.3165, -72.62611, 'Northampton', 'MA', 'A private collection has accumulated thousands of beer cans spanning decades of packaging, brewing history and graphic design. The walls of cans turn an ordinary object into a dense visual archive; this is a small private museum, so visitors should verify current access before making a dedicated trip.', 'limited', 'https://www.roadsideamerica.com/location/ma', null, 'America/New_York', now()),
  ('Grave of Albert DeSalvo', 'grave-of-albert-desalvo', 'weird-history', 42.52787, -70.92866, 'Peabody', 'MA', 'Albert DeSalvo, who confessed to being the Boston Strangler, is buried in Puritan Lawn Memorial Park. DNA later linked him to the murder of Mary Sullivan, although historians and investigators have long questioned whether he was responsible for every killing attributed to the Strangler. Visit only during cemetery hours.', 'limited', 'https://www.atlasobscura.com/places/grave-of-the-boston-strangler', null, 'America/New_York', now()),
  ('Wally the Stegosaurus', 'wally-the-stegosaurus', 'roadside-oddities', 42.44728, -73.2542, 'Pittsfield', 'MA', 'A life-size stegosaurus named Wally stands outside the Berkshire Museum. The dinosaur has become a local landmark and a preview of the museum''s natural-history collections, appearing unexpectedly along a downtown streetscape rather than in a prehistoric park.', 'open', 'https://www.atlasobscura.com/places/wally-the-stegosaurus', null, 'America/New_York', now()),
  ('National Monument to the Forefathers', 'national-monument-to-the-forefathers', 'weird-history', 41.96014, -70.67585, 'Plymouth', 'MA', 'An enormous 81-foot granite monument dominates a hill above Plymouth. Completed in the nineteenth century, it surrounds a towering central figure of Faith with allegorical sculptures representing morality, law, education and liberty, giving it the scale and visual drama of a fantasy monument.', 'open', 'https://www.atlasobscura.com/places/national-monument-to-the-forefathers', null, 'America/New_York', now()),
  ('Sacrifice Rock', 'sacrifice-rock', 'weird-history', 41.90227, -70.59672, 'Plymouth', 'MA', 'A large glacial boulder beside Old Sandwich Road is historically associated with Wampanoag travelers leaving offerings before journeys. Colonial writers later called it Sacrifice Rock. The site is best understood as a surviving landscape feature tied to Indigenous tradition rather than a supernatural roadside attraction.', 'roadside', 'https://www.hmdb.org/m.asp?m=73683', null, 'America/New_York', now()),
  ('Mama Shug — Shark Made of Plastic Trash', 'mama-shug-shark-made-of-plastic-trash', 'roadside-oddities', 42.04416, -70.21647, 'Provincetown', 'MA', 'A giant shark sculpture near Herring Cove Beach is assembled from plastic debris collected from beaches. Nicknamed Mama Shug, the creature turns marine trash into an oversized predator while making the scale of ocean pollution impossible to ignore.', 'open', 'https://www.atlasobscura.com/places/mama-shug', null, 'America/New_York', now()),
  ('USS Salem', 'uss-salem', 'museums', 42.24232, -70.97113, 'Quincy', 'MA', 'The massive Cold War-era heavy cruiser USS Salem is preserved as a museum ship at the former Quincy shipyard. Visitors can move through cramped compartments, machinery spaces and gun areas inside a vessel large enough to feel like a floating industrial complex.', 'limited', 'https://www.uss-salem.org/', 'https://www.uss-salem.org/', 'America/New_York', now()),
  ('World''s Most Nearly Perfect Sphere', 'worlds-most-nearly-perfect-sphere', 'roadside-oddities', 42.25275, -71.00232, 'Quincy', 'MA', 'A polished granite ball six feet in diameter and weighing about 9.5 tons sits near Quincy City Hall. The 1925 monument was once promoted by Ripley''s Believe It or Not as the ''most nearly perfect sphere in the world,'' an absurdly precise claim for an enormous stone ball left outdoors for a century.', 'open', 'https://www.roadsideamerica.com/tip/21365', null, 'America/New_York', now()),
  ('The House of the Seven Gables', 'the-house-of-the-seven-gables', 'weird-history', 42.52176, -70.88351, 'Salem', 'MA', 'This seventeenth-century mansion inspired Nathaniel Hawthorne''s 1851 novel and has accumulated centuries of architectural alterations, hidden spaces and family stories. The museum complex includes Hawthorne''s birthplace and guided access to the famously named house.', 'limited', 'https://www.atlasobscura.com/places/house-of-the-seven-gables', 'https://7gables.org/', 'America/New_York', now()),
  ('The Satanic Temple Salem Art Gallery', 'the-satanic-temple-salem-art-gallery', 'museums', 42.53138, -70.88911, 'Salem', 'MA', 'The headquarters and gallery of The Satanic Temple displays occult-themed art, organizational history and a large bronze Baphomet figure. The group describes itself as nontheistic, so the site is better understood as contemporary religious and political culture than evidence of literal devil worship.', 'limited', 'https://www.atlasobscura.com/places/the-satanic-temple-salem-art-gallery', 'https://www.salemartgallery.com/', 'America/New_York', now()),
  ('Salem Witch Museum', 'salem-witch-museum', 'weird-history', 42.52371, -70.89113, 'Salem', 'MA', 'One of Salem''s longest-running witch-trial attractions uses life-size stage sets and narration to tell the story of the 1692 crisis, followed by an exhibit examining changing ideas about witches. Its presentation is theatrical, making it distinct from the city''s preserved trial sites and memorials.', 'limited', 'https://salemwitchmuseum.com/', 'https://salemwitchmuseum.com/', 'America/New_York', now()),
  ('Salem Wax Museum', 'salem-wax-museum', 'haunted', 42.52027, -70.89154, 'Salem', 'MA', 'Wax figures depict scenes and characters from Salem''s colonial history and witch-trial era in an intentionally old-school attraction. The museum is small and theatrical rather than academic, making the vintage presentation itself part of the OddWay appeal.', 'limited', 'https://www.salemwaxmuseum.com/', 'https://www.salemwaxmuseum.com/', 'America/New_York', now()),
  ('Witch History Museum', 'witch-history-museum', 'haunted', 42.52149, -70.89406, 'Salem', 'MA', 'A guided underground attraction recreates scenes from the Salem witch trials using figures, narration and dungeon-like spaces. It overlaps thematically with other Salem museums, but the basement walkthrough and reconstructed village scenes provide a distinct traveler experience.', 'limited', 'https://www.witchhistorymuseum.com/', 'https://www.witchhistorymuseum.com/', 'America/New_York', now()),
  ('Barney Family Mausoleum — Sphinx Tomb', 'barney-family-mausoleum-sphinx-tomb', 'weird-history', 42.07456, -72.58041, 'Springfield', 'MA', 'A bronze sphinx guards the entrance to the Barney family mausoleum in Forest Park. The Egyptian-style tomb was commissioned by wealthy industrialist Everett Hosmer Barney and looks dramatically out of place amid the surrounding New England landscape.', 'open', 'https://www.atlasobscura.com/places/barney-family-mausoleum', null, 'America/New_York', now()),
  ('Ashland Witch Caves', 'ashland-witch-caves', 'weird-history', 42.27074, -71.47588, 'Ashland', 'MA', 'Collapsed rock shelters in Ashland Town Forest are traditionally associated with people fleeing persecution connected with the Salem witch trials. Very little of the original cave space remains, but the location preserves the broader story of displaced families who settled in the area once known as Salem End.', 'open', 'https://www.atlasobscura.com/places/ashland-witch-caves', null, 'America/New_York', now()),
  ('The Devil''s Den', 'the-devils-den', 'folklore', 42.26016, -71.44783, 'Ashland', 'MA', 'A small talus cave beside Ashland High School was once feared by colonial settlers as a possible hiding place of the Devil. Archaeological evidence points instead to earlier Indigenous use, giving the cave both genuine history and a layer of Puritan-era supernatural folklore.', 'open', 'https://www.atlasobscura.com/places/the-devils-den', null, 'America/New_York', now()),
  ('Stone''s Public House', 'stones-public-house', 'haunted', 42.25969, -71.46458, 'Ashland', 'MA', 'This 1830s former railroad inn openly embraces stories of apparitions, unexplained sounds and other paranormal activity. It remains an operating Irish-American restaurant and pub, making it one of the easiest alleged-haunting stops in Massachusetts to visit without trespassing or joining a special tour.', 'open', 'https://www.atlasobscura.com/places/stones-public-house', 'https://www.stonespublichouse.com/', 'America/New_York', now()),
  ('Plum Island Pink House', 'plum-island-pink-house', 'roadside-oddities', 42.79706, -70.83062, 'Newbury', 'MA', 'An isolated pink house stands in the salt marsh beside the Plum Island Turnpike, surrounded by decades of local stories about divorce, spite and why anyone would build there. The property has faced repeated preservation and demolition controversies; view only from legal public areas and never enter the house.', 'roadside', 'https://www.atlasobscura.com/places/plum-island-pink-house', null, 'America/New_York', now()),
  ('Old Franklin Park Zoo Bear Pens', 'old-franklin-park-zoo-bear-pens', 'weird-history', 42.30248, -71.087, 'Boston', 'MA', 'Concrete and stone remnants of the old Franklin Park Zoo bear enclosures survive in the woods, long after the animals moved to modern habitats. The abandoned pens were also used as a filming location for ''Mystic River.'' Current signs prohibit entry into the structures, so view them only from permitted trails and areas.', 'roadside', 'https://www.atlasobscura.com/places/old-franklin-park-zoo-bear-pens', null, 'America/New_York', now()),
  ('Echo Bridge', 'echo-bridge', 'roadside-oddities', 42.31478, -71.22698, 'Newton', 'MA', 'A nineteenth-century aqueduct bridge over the Charles River creates an unusually strong repeating echo beneath its stone arch. A public stairway leads to the echo platform, where a shout or clap can bounce back several times in rapid succession.', 'open', 'https://www.atlasobscura.com/places/echo-bridge', null, 'America/New_York', now()),
  ('Forbes Pigment Collection', 'forbes-pigment-collection', 'museums', 42.37418, -71.11408, 'Cambridge', 'MA', 'Thousands of pigment samples at Harvard range from rare mineral colors to historically toxic compounds and the infamous ''mummy brown,'' once manufactured using ground Egyptian remains. The collection belongs to the museum''s conservation department; portions can be seen from public museum space, while direct research access is restricted.', 'limited', 'https://www.atlasobscura.com/places/forbes-pigment-collection', 'https://harvardartmuseums.org/', 'America/New_York', now()),
  ('Mice Manor', 'mice-manor', 'roadside-oddities', 42.54227, -70.88483, 'Beverly', 'MA', 'Inside a Beverly artisan shop is an elaborate black dollhouse populated by taxidermied mice dressed as horror and pop-culture characters. Residents have included miniature versions of Lizzie Borden, Norman Bates and Buffalo Bill, and the tiny cast changes as individual pieces are sold.', 'open', 'https://www.atlasobscura.com/places/mice-manor', null, 'America/New_York', now()),
  ('Emerson''s Pickle Factory Plaque', 'emersons-pickle-factory-plaque', 'weird-history', 42.4007, -71.11733, 'Somerville', 'MA', 'A stone marker and replica jars commemorate George W. Emerson''s once-successful pickle factory, which burned in the nineteenth century. It is a wonderfully specific monument to a vanished condiment empire, sitting near Somerville''s much older Powder House.', 'open', 'https://www.atlasobscura.com/places/george-w-emersons-pickle-factory-plaque', null, 'America/New_York', now()),
  ('Holliston Moon Tree', 'holliston-moon-tree', 'weird-history', 42.20739, -71.4272, 'Holliston', 'MA', 'This American sycamore grew from a seed carried around the Moon aboard Apollo 14 in 1971. Massachusetts received two Moon Tree seeds for the Bicentennial; the other tree died, leaving Holliston''s specimen as the state''s surviving living link to the mission.', 'open', 'https://www.atlasobscura.com/places/apollo-14-holliston-moon-tree', null, 'America/New_York', now()),
  ('Upton Chamber', 'upton-chamber', 'folklore', 42.17601, -71.59782, 'Upton', 'MA', 'A long stone-lined underground chamber with a corbelled roof sits in Heritage Park, and its original purpose has puzzled researchers for generations. Archaeological study points to a historic construction rather than exotic ancient origins, but the dark artificial cave remains one of Massachusetts'' better physical mysteries.', 'open', 'https://www.atlasobscura.com/places/upton-chamber', null, 'America/New_York', now()),
  ('Norumbega Tower', 'norumbega-tower', 'folklore', 42.35367, -71.26361, 'Weston', 'MA', 'A stone tower beside the Charles River marks the place nineteenth-century scholar Eben Horsford believed was a Norse fort connected to the legendary city of Norumbega. His Viking theory was not supported by convincing archaeological evidence, leaving the monument as an impressive memorial to a historical idea that did not hold up.', 'open', 'https://www.atlasobscura.com/places/norumbega-tower', null, 'America/New_York', now()),
  ('Where Shute Fell', 'where-shute-fell', 'folklore', 42.45232, -71.09628, 'Stoneham', 'MA', 'A lonely stone on Great Island in Spot Pond bears only the words ''WHERE SHUTE FELL.'' Stories propose a duel, a wrestling match and even a drunken accident, but the meaning was already uncertain in the nineteenth century. Reaching the island requires authorized boat access or a rental from the permitted Spot Pond boating operation.', 'limited', 'https://www.atlasobscura.com/places/where-shute-fell', null, 'America/New_York', now()),
  ('John Harvard ''Statue of Three Lies''', 'john-harvard-statue-of-three-lies', 'weird-history', 42.37432, -71.11725, 'Cambridge', 'MA', 'Harvard''s famous bronze founder statue is nicknamed the Statue of Three Lies: the figure is not actually modeled on John Harvard, he was not technically the university''s founder, and the inscribed founding date does not match the institution''s history precisely. Students and tourists also rub its shoe for luck.', 'open', 'https://www.atlasobscura.com/places/john-harvard-statue-of-three-lies', null, 'America/New_York', now()),
  ('Mount Greylock War Memorial Tower', 'mount-greylock-war-memorial-tower', 'roadside-oddities', 42.63758, -73.16622, 'Adams', 'MA', 'Massachusetts'' highest summit is crowned by a 93-foot granite war memorial tower shaped like an austere lighthouse. The beacon and mountaintop setting make it look almost otherworldly above the Berkshires. Summit-road access is seasonal, while hiking access depends on current trail and weather conditions.', 'limited', 'https://www.atlasobscura.com/places/mount-greylock', null, 'America/New_York', now()),
  ('Goddard Rocket Launching Site', 'goddard-rocket-launching-site', 'weird-history', 42.21941, -71.81119, 'Auburn', 'MA', 'A modest rocket-shaped obelisk marks the field where Robert H. Goddard launched the world''s first successful liquid-fueled rocket on March 16, 1926. The flight lasted only a few seconds, but the experiment helped lay the groundwork for modern rocketry and spaceflight.', 'open', 'https://www.atlasobscura.com/places/goddard-rocket-launching-site', null, 'America/New_York', now()),
  ('Charlton Route 20 Cow Tunnel', 'charlton-route-20-cow-tunnel', 'roadside-oddities', 42.14659, -71.93708, 'Charlton', 'MA', 'A narrow concrete tunnel built in 1926 allowed cattle to pass safely beneath busy Route 20 instead of crossing traffic. The unusual agricultural underpass was preserved during recent trail work and now sits along the Midstate Trail as a wonderfully specific piece of roadside infrastructure.', 'open', 'https://www.atlasobscura.com/places/charlton-route-20-cow-tunnel', null, 'America/New_York', now()),
  ('Leif Erikson Plaque', 'leif-erikson-plaque', 'weird-history', 42.37331, -71.13431, 'Cambridge', 'MA', 'A small plaque marks the spot nineteenth-century chemist Eben Horsford claimed was the site of Leif Erikson''s home from around the year 1000. Mainstream archaeology has not supported Horsford''s theory, turning the marker into a physical relic of America''s enthusiasm for speculative Viking history.', 'open', 'https://www.atlasobscura.com/places/leif-erikson-plaque', null, 'America/New_York', now()),
  ('Marconi Wireless Station Site', 'marconi-wireless-station-site', 'weird-history', 41.90466, -69.98479, 'Wellfleet', 'MA', 'The dunes preserve the site of Guglielmo Marconi''s enormous wireless station, where a transatlantic message from President Theodore Roosevelt was sent to King Edward VII in 1903. Most of the original station has vanished into the eroding Cape Cod shoreline, leaving interpretive remains and an unusually windswept communications landmark.', 'open', 'https://www.atlasobscura.com/places/marconi-wireless-station-site', null, 'America/New_York', now()),
  ('Deed to God Rock', 'deed-to-god-rock', 'roadside-oddities', 42.25627, -71.86239, 'Worcester', 'MA', 'In 1840, miller and Millerite believer Solomon Parsons Jr. carved a roughly 215-word deed into a boulder declaring ten surrounding acres conveyed to God. Parts of the inscription remain legible along trails in the city-owned God''s Acre conservation land.', 'open', 'https://www.roadsideamerica.com/tip/59714', 'https://www.worcesterma.gov/city-parks', 'America/New_York', now()),
  ('The Boston Stone', 'the-boston-stone', 'folklore', 42.36185, -71.0567, 'Boston', 'MA', 'A stone sphere embedded in a downtown wall is labeled ''Boston Stone 1737,'' but exactly what it originally signified remains debated. Explanations range from a paint-grinding stone to a deliberately manufactured historical curiosity, making the uncertainty part of the attraction.', 'open', 'https://www.atlasobscura.com/places/the-boston-stone-boston-massachusetts', null, 'America/New_York', now()),
  ('Arthur Fiedler Memorial', 'arthur-fiedler-memorial', 'roadside-oddities', 42.35651, -71.07545, 'Boston', 'MA', 'The enormous head of Boston Pops conductor Arthur Fiedler is assembled from dozens of stacked aluminum plates. From a distance the face looks solid, while closer views break it into thin shimmering slices, creating an unusually effective optical illusion along the Charles River Esplanade.', 'open', 'https://www.atlasobscura.com/places/arthur-fiedler-memorial', null, 'America/New_York', now()),
  ('Cocoanut Grove Fire Plaque', 'cocoanut-grove-fire-plaque', 'weird-history', 42.34998, -71.06814, 'Boston', 'MA', 'A plaque marks the neighborhood where the Cocoanut Grove nightclub burned in 1942, killing 492 people. The disaster led to major changes in fire codes, emergency exits and burn treatment, yet very little of the infamous nightclub is visible today beyond the memorial marker.', 'open', 'https://www.atlasobscura.com/places/cocoanut-grove-fire-plaque', null, 'America/New_York', now()),
  ('Rollstone Boulder', 'rollstone-boulder', 'roadside-oddities', 42.58668, -71.80595, 'Fitchburg', 'MA', 'When quarrying threatened a 110-ton glacial boulder beloved by Fitchburg residents, workers blasted it into pieces, hauled those pieces downtown and painstakingly reassembled the rock on a traffic island. The resulting landmark is both an Ice Age remnant and a giant stone puzzle.', 'open', 'https://www.atlasobscura.com/places/rollstone-boulder', null, 'America/New_York', now()),
  ('Ponyhenge', 'ponyhenge', 'roadside-oddities', 42.40193, -71.32879, 'Lincoln', 'MA', 'A mysterious herd of rocking horses, hobby horses and plastic ponies gathers in a roadside field and continually changes as strangers add, remove and rearrange animals. The privately owned field has become an evolving folk-art installation with no formal curator.', 'open', 'https://www.atlasobscura.com/places/ponyhenge', null, 'America/New_York', now()),
  ('Emily the Cow Statue', 'emily-the-cow-statue', 'roadside-oddities', 42.24294, -71.36948, 'Sherborn', 'MA', 'A bronze cow marks the grave of Emily, who escaped a slaughterhouse in 1995 and survived hidden in the woods for weeks before being rescued by the Peace Abbey. She became a local symbol of animal welfare, and the memorial preserves one of Massachusetts'' strangest animal-escape stories.', 'open', 'https://www.atlasobscura.com/places/emily-the-cow-statue-peace-abbey-sherborn-massachusetts', null, 'America/New_York', now()),
  ('Titanic Museum', 'titanic-museum', 'museums', 42.15962, -72.50026, 'Springfield', 'MA', 'The Titanic Historical Society maintains a surprisingly deep collection of artifacts connected with the doomed ocean liner, many donated by survivors and their families. The museum occupies an unassuming building in Indian Orchard and includes documents, personal objects and a large ship model. Verify current hours before making a dedicated trip.', 'limited', 'https://www.atlasobscura.com/places/the-titanic-museum-springfield-massachusetts', null, 'America/New_York', now()),
  ('Optical Heritage Museum', 'optical-heritage-museum', 'museums', 42.08035, -72.03516, 'Southbridge', 'MA', 'Southbridge''s long history as an optical-manufacturing center survives in a museum filled with antique spectacles, lenses, machinery, microscopes and experimental eyewear. The collection follows the evolution of vision technology through objects that range from elegant to genuinely bizarre.', 'limited', 'https://www.atlasobscura.com/places/optical-heritage-museum', 'https://www.opticalheritagemuseum.org/', 'America/New_York', now()),
  ('Santarella', 'santarella', 'roadside-oddities', 42.25466, -73.21422, 'Tyringham', 'MA', 'A storybook estate in the Berkshires includes a dramatically curved shingle-roofed structure commonly called the Gingerbread House. Sculptor Henry Hudson Kitson reshaped the property into an architectural fantasy that looks closer to a fairy-tale illustration than a conventional New England home. Access is limited to current events, rentals or authorized visits.', 'limited', 'https://www.atlasobscura.com/places/santarella', null, 'America/New_York', now()),
  ('Westford Knight', 'westford-knight', 'weird-history', 42.5874, -71.43437, 'Westford', 'MA', 'Marks on a roadside rock have been promoted as the carved image of a medieval Scottish knight and evidence of a pre-Columbian Templar expedition to New England. Most researchers favor natural weathering and later human markings, but a plaque and knight statue ensure the disputed theory remains physically memorialized.', 'open', 'https://www.atlasobscura.com/places/westford-knight', null, 'America/New_York', now()),
  ('Burnside Fountain — Turtle Boy', 'burnside-fountain-turtle-boy', 'roadside-oddities', 42.26139, -71.80032, 'Worcester', 'MA', 'A nude boy rides an enormous sea turtle at the center of this eccentric downtown fountain. Officially named the Burnside Fountain, the sculpture is universally known as Turtle Boy and has become one of Worcester''s most recognizable unofficial mascots.', 'open', 'https://www.atlasobscura.com/places/burnside-fountain-aka-turtle-boy', null, 'America/New_York', now()),
  ('The Mysterious Witch Bonney', 'the-mysterious-witch-bonney', 'folklore', 42.62854, -71.29266, 'Lowell', 'MA', 'A nineteenth-century cemetery statue of a woman has accumulated stories that her dress changes length, that she moves, and that offerings left at the grave mysteriously disappear. The monument is real; the supernatural claims are cemetery folklore. Visit Lowell Cemetery respectfully and only during permitted hours.', 'limited', 'https://www.atlasobscura.com/places/mysterious-witch-bonney', null, 'America/New_York', now()),
  ('Solitude Stone', 'solitude-stone', 'folklore', 42.00148, -71.01711, 'West Bridgewater', 'MA', 'A boulder engraved in 1852 with a melancholy poem about solitude sits in the woods near the Bridgewater Triangle. Later stories connected the stone with death, disappearance and paranormal activity, although those claims are folklore layered onto a genuine nineteenth-century inscription.', 'open', 'https://www.atlasobscura.com/places/solitude-stone', null, 'America/New_York', now()),
  ('Spooner Well', 'spooner-well', 'weird-history', 42.22553, -72.085, 'Brookfield', 'MA', 'A marker identifies the well where Joshua Spooner''s body was dumped after his wife Bathsheba arranged his murder in 1778. The resulting trial ended with Bathsheba and three accomplices being executed and became one of colonial Massachusetts'' most notorious criminal cases.', 'open', 'https://www.atlasobscura.com/places/spooner-well', null, 'America/New_York', now()),
  ('Susanna Jayne Headstone', 'susanna-jayne-headstone', 'weird-history', 42.5103, -70.84642, 'Marblehead', 'MA', 'This extraordinarily elaborate 1776 gravestone crowds together a skeleton, scythe, sun, moon, ouroboros, angels and other mortality symbols. It is an unusually dense example of New England funerary art and looks closer to an occult illustration than a typical colonial marker. Visit the burial ground respectfully during permitted hours.', 'limited', 'https://www.atlasobscura.com/places/susanna-jayne-headstone', null, 'America/New_York', now()),
  ('Deerfield Massacre Mass Grave', 'deerfield-massacre-mass-grave', 'weird-history', 42.54539, -72.60816, 'Deerfield', 'MA', 'A communal grave in Deerfield marks the burial of residents killed during the 1704 French and Indigenous raid on the English settlement. The site is a serious memorial connected with a violent colonial frontier conflict rather than a paranormal attraction, but its concentrated history makes it a significant OddWay stop.', 'open', 'https://www.atlasobscura.com/places/deerfield-massacre-mass-grave', null, 'America/New_York', now()),
  ('Milford Irish Round Tower', 'milford-irish-round-tower', 'roadside-oddities', 42.15637, -71.50831, 'Milford', 'MA', 'A tall pink-granite tower modeled after medieval Irish round towers rises unexpectedly from St. Mary''s Cemetery. Built as a memorial to local Irish immigrants, it gives the cemetery the silhouette of an ancient monastic site transplanted into Massachusetts.', 'open', 'https://www.atlasobscura.com/places/milford-irish-round-tower', null, 'America/New_York', now()),
  ('Her Vacant Chair', 'her-vacant-chair', 'weird-history', 41.92012, -71.08924, 'Taunton', 'MA', 'The grave of three-year-old Pearl French is marked by a carved stone rocking chair, an unusually intimate Victorian-style memorial. Local stories later attached ghostly movement and other paranormal claims to the chair, but those remain folklore. Visit the cemetery respectfully during open hours.', 'limited', 'https://www.atlasobscura.com/places/her-vacant-chair', null, 'America/New_York', now()),
  ('Grave of Don Featherstone', 'grave-of-don-featherstone', 'weird-history', 42.36606, -71.62873, 'Berlin', 'MA', 'Don Featherstone, designer of the iconic plastic pink lawn flamingo, is buried beneath a marker decorated with a flock of flamingos and an inscription crediting him as their original creator. It is an appropriately kitschy final memorial for one of America''s most recognizable lawn ornaments.', 'limited', 'https://www.atlasobscura.com/places/don-featherstone-grave', null, 'America/New_York', now()),
  ('Graves of David and Mabel Todd', 'graves-of-david-and-mabel-todd', 'weird-history', 42.38838, -72.51175, 'Amherst', 'MA', 'Astronomer David Todd repeatedly traveled around the world chasing solar eclipses only to encounter clouds and other failures, while his wife Mabel Loomis Todd became crucial to the publication of Emily Dickinson''s poetry. Their unusual memorials incorporate astronomical and botanical imagery tied to their lives.', 'limited', 'https://www.atlasobscura.com/places/graves-of-david-and-mabel-todd', null, 'America/New_York', now()),
  ('Grave of Dunkin'' Donuts Founder', 'grave-of-dunkin-donuts-founder', 'weird-history', 42.14592, -71.16848, 'Sharon', 'MA', 'William Rosenberg, founder of Dunkin'' Donuts, is buried in Sharon Memorial Park. The otherwise conventional grave gives Massachusetts travelers a physical endpoint to the story of a regional doughnut-and-coffee business that grew into an international chain. Check cemetery access rules before visiting.', 'limited', 'https://www.atlasobscura.com/places/grave-of-dunkin-donuts-founder-massachusetts', null, 'America/New_York', now()),
  ('The Parker Brothers'' Grave', 'the-parker-brothers-grave', 'weird-history', 42.52433, -70.91135, 'Salem', 'MA', 'Game-company founders George, Charles and Edward Parker are buried in Salem, linking the city to the company behind generations of American board games. Parker Brothers later published titles ranging from Monopoly and Clue to the Ouija talking board, giving the family plot an appropriately game-filled legacy.', 'limited', 'https://www.atlasobscura.com/places/the-grave-of-the-parker-brothers', null, 'America/New_York', now()),
  ('Mysterious Chappaquiddick Shipwreck', 'mysterious-chappaquiddick-shipwreck', 'weird-history', 41.37418, -70.4494, 'Edgartown', 'MA', 'The shifting sand of Chappaquiddick periodically exposes wooden wreckage believed to belong to the Christina, lost in 1866. One survivor reportedly clung to the mast for more than two days. Visibility changes with storms and sand movement, and reaching the area can require ferry and beach-access planning.', 'limited', 'https://www.atlasobscura.com/places/mysterious-chappaquiddick-shipwreck', null, 'America/New_York', now()),
  ('The Brickyard', 'the-brickyard', 'weird-history', 41.3769, -70.74429, 'Chilmark', 'MA', 'A tall brick chimney and scattered machinery survive from a Martha''s Vineyard brickmaking operation with roots reaching back to the seventeenth century. A formal conservation trail leads through the site, where industrial ruins sit unexpectedly amid coastal woodland.', 'open', 'https://www.atlasobscura.com/places/the-brickyard', null, 'America/New_York', now()),
  ('Franklin Park Overlook Shelter Ruins', 'franklin-park-overlook-shelter-ruins', 'weird-history', 42.308, -71.09716, 'Boston', 'MA', 'Stone walls and arches survive from an Olmsted-era field house in Franklin Park. The shelter burned in the twentieth century and later became a setting for outdoor concerts before settling into its current life as a picturesque public ruin along park trails.', 'open', 'https://www.atlasobscura.com/places/franklin-parks-overlook-shelter-ruins', null, 'America/New_York', now()),
  ('Mineral Hills Abandoned Rock Quarry', 'mineral-hills-abandoned-rock-quarry', 'weird-history', 42.31002, -72.73117, 'Northampton', 'MA', 'An abandoned quarry hides along conservation trails in Northampton''s Mineral Hills. The exposed rock walls and flooded or overgrown workings create a dramatic industrial scar inside otherwise wooded public land. Stay on legal trails and keep back from unstable quarry edges.', 'open', 'https://www.atlasobscura.com/places/mineral-hills-abandoned-rock-quarry', null, 'America/New_York', now()),
  ('Hawley Beehive Kiln', 'hawley-beehive-kiln', 'weird-history', 42.56312, -72.87948, 'Hawley', 'MA', 'A remarkably intact nineteenth-century stone charcoal kiln sits along a short woodland trail. The beehive-shaped structure once converted huge amounts of local wood into charcoal for industry and is among the best-preserved examples of its type in New England.', 'open', 'https://www.atlasobscura.com/places/hawley-beehive-kiln', null, 'America/New_York', now()),
  ('Assabet River National Wildlife Refuge — WWII Bunkers', 'assabet-river-national-wildlife-refuge-wwii-bunkers', 'weird-history', 42.40785, -71.47149, 'Sudbury', 'MA', 'Dozens of sealed concrete ammunition bunkers from World War II remain scattered through today''s wildlife refuge. The military storage landscape has been reclaimed by forest, wetlands and trails, producing an unusual mix of bird habitat and wartime infrastructure. The bunker interiors are closed.', 'open', 'https://www.atlasobscura.com/places/assabet-river-national-wildlife-refuge', 'https://www.fws.gov/refuge/assabet-river', 'America/New_York', now()),
  ('Fort Taber Park', 'fort-taber-park', 'weird-history', 41.59498, -70.90247, 'New Bedford', 'MA', 'Multiple generations of coastal defenses occupy this New Bedford peninsula, including granite Fort Rodman, concrete batteries and underground-looking military structures. Much of the park can be explored from public paths, while individual fort interiors and restricted areas open only under current park rules or special programs.', 'open', 'https://www.atlasobscura.com/places/fort-taber-park-new-bedford', null, 'America/New_York', now()),
  ('Expired Parking Meter Gravestone', 'expired-parking-meter-gravestone', 'weird-history', 42.66632, -73.01175, 'Florida', 'MA', 'Gordy and Joyce Burdick''s grave incorporates an actual parking meter labeled as expired, turning a roadside object into a permanent cemetery joke. The unusual marker sits in a small burial ground near the Hoosac Tunnel region. Visit respectfully during permitted hours.', 'limited', 'https://www.atlasobscura.com/places/expired-parking-meter-gravestone', null, 'America/New_York', now()),
  ('Old Stone Church', 'old-stone-church', 'weird-history', 42.37504, -71.78286, 'West Boylston', 'MA', 'A roofless stone church stands beside the Wachusett Reservoir as one of the few visible remnants of a community displaced when the reservoir was created. The building was stripped and preserved rather than submerged, leaving a lonely Gothic-looking shell beside the water.', 'open', 'https://www.atlasobscura.com/places/old-stone-church', null, 'America/New_York', now()),
  ('Metropolitan State Hospital — Surviving Administration Building', 'metropolitan-state-hospital-surviving-administration-building', 'weird-history', 42.40546, -71.21361, 'Waltham', 'MA', 'Most of this former state psychiatric hospital was demolished or redeveloped after its 1992 closure, but the old administration building survives beside public trails and open space. The institution''s history includes documented controversy over neglect and abuse as well as later ghost stories. The surrounding area is public; entering the surviving building is not permitted.', 'limited', 'https://www.atlasobscura.com/places/metropolitan-state-hospital-msh', null, 'America/New_York', now()),
  ('Medfield State Hospital', 'medfield-state-hospital', 'weird-history', 42.20722, -71.33129, 'Medfield', 'MA', 'More than 35 buildings from a former state psychiatric hospital remain standing across an unusually intact campus. The town allows daytime visitors to walk many outdoor areas, and the property has appeared in films including ''Shutter Island'' and ''Knives Out.'' Every building interior is off-limits, and construction or filming can close sections without much notice.', 'limited', 'https://www.atlasobscura.com/places/medfield-state-hospital', null, 'America/New_York', now()),
  ('Holyoke''s Frog Circus', 'holyokes-frog-circus', 'museums', 42.20479, -72.61735, 'Holyoke', 'MA', 'A miniature circus populated by taxidermied frogs performs frozen acrobatics inside the Wistariahurst visitor area. The bizarre tableau belongs to a long tradition of anthropomorphic taxidermy and is one of Massachusetts'' smallest but most memorable museum oddities. Check current visitor-center hours.', 'limited', 'https://www.atlasobscura.com/places/holyoke-frog-circus', null, 'America/New_York', now()),
  ('Babson Globe', 'babson-globe', 'roadside-oddities', 42.29773, -71.26411, 'Wellesley', 'MA', 'A 28-foot rotating globe weighing roughly 25 tons dominates the Babson College campus. Built at the direction of eccentric businessman Roger Babson, the enormous sphere was designed as an educational model of the world and remains one of the largest rotating globes ever constructed.', 'open', 'https://www.atlasobscura.com/places/babson-globe', null, 'America/New_York', now()),
  ('Temple Bell', 'temple-bell', 'weird-history', 42.34134, -71.09429, 'Boston', 'MA', 'A huge seventeenth-century Japanese temple bell sits outdoors near the Back Bay Fens. Taken from Japan as wartime scrap after World War II, it was later formally presented to Boston as a symbol of peace, giving the object an unusually complicated journey from temple artifact to public monument.', 'open', 'https://www.atlasobscura.com/places/temple-bell', null, 'America/New_York', now()),
  ('Harvard Bridge Houdini Plaque', 'harvard-bridge-houdini-plaque', 'weird-history', 42.35213, -71.08991, 'Boston', 'MA', 'A plaque on the Harvard Bridge commemorates Harry Houdini''s 1908 leap into the Charles River while shackled in chains. Thousands reportedly watched the escape artist make the stunt, and the small marker preserves a surprisingly dramatic piece of Boston spectacle history.', 'open', 'https://www.atlasobscura.com/places/harvard-bridge-houdini-plaque', null, 'America/New_York', now()),
  ('Monumental Stone Sphere', 'monumental-stone-sphere', 'weird-history', 42.37824, -71.11467, 'Cambridge', 'MA', 'A massive, nearly perfect stone sphere from pre-Columbian Costa Rica sits outside Harvard''s Peabody Museum. Weighing thousands of pounds, it belongs to a mysterious archaeological tradition in which craftspeople shaped enormous boulders into remarkably smooth geometric forms.', 'open', 'https://www.atlasobscura.com/places/monumental-stone-sphere', null, 'America/New_York', now()),
  ('Burned at the Stake Monument', 'burned-at-the-stake-monument', 'weird-history', 42.2955, -71.26557, 'Wellesley', 'MA', 'A stark stone monument on the Babson College campus memorializes Protestant martyr John Rogers, who was executed by burning in England in 1555. College founder Roger Babson believed Rogers was an ancestor and installed the memorial as one of several unusual monuments scattered around campus.', 'open', 'https://www.atlasobscura.com/places/burned-at-the-stake-monument-babson', null, 'America/New_York', now()),
  ('Wannalancit Mills Smokestack Christmas Tree', 'wannalancit-mills-smokestack-christmas-tree', 'roadside-oddities', 42.64933, -71.31612, 'Lowell', 'MA', 'Each holiday season, a huge conical framework of lights transforms the top of a mill smokestack into an enormous elevated Christmas tree. The industrial chimney becomes a surreal seasonal landmark visible across Lowell, generally appearing from late fall into winter.', 'limited', 'https://www.atlasobscura.com/places/wannalancit-mills-smokestack-christmas-tree', null, 'America/New_York', now()),
  ('Salty the Seahorse', 'salty-the-seahorse', 'roadside-oddities', 41.66367, -70.81218, 'Mattapoisett', 'MA', 'A towering blue-green seahorse survives from a 1950s roadside gift shop and now stands preserved in a small public park. Salty is pure mid-century roadside advertising: oversized, cheerful and completely unrelated in scale to the animal it represents.', 'open', 'https://www.atlasobscura.com/places/salty-the-seahorse', null, 'America/New_York', now()),
  ('Gloucester Sea Serpent Statue', 'gloucester-sea-serpent-statue', 'cryptids', 42.61383, -70.66176, 'Gloucester', 'MA', 'A serpentine sculpture on the Gloucester Harborwalk commemorates the enormous sea creature reported by numerous witnesses off Cape Ann in 1817. Explanations for the historic sightings have ranged from ordinary marine animals to misidentification, but the Gloucester Sea Serpent remains one of Massachusetts'' defining cryptid legends.', 'open', 'https://www.atlasobscura.com/places/gloucester-sea-serpent-statue', 'https://harborwalk.gloucester-ma.gov/locations/19-the-sea-serpent/', 'America/New_York', now()),
  ('Head of the Egopantis', 'head-of-the-egopantis', 'cryptids', 42.58431, -71.64648, 'Shirley', 'MA', 'The Bull Run Restaurant displays the mounted ''head'' of a legendary creature called the Egopantis along with the musket said to have killed it in colonial times. The tavern presents the tale with a straight face, although the creature is almost certainly a modern fearsome-critter-style legend rather than an unknown species.', 'open', 'https://www.atlasobscura.com/places/head-of-the-egopantis-massachusetts', 'https://www.bullrunrestaurant.com/', 'America/New_York', now()),
  ('Grave of the Smiley Face Inventor', 'grave-of-the-smiley-face-inventor', 'weird-history', 42.23465, -71.83737, 'Worcester', 'MA', 'Harvey Ball, the Worcester artist who created the familiar yellow Smiley Face in 1963, is buried beneath a granite marker displaying his own cheerful design. Ball reportedly created the image in minutes for an insurance-company morale campaign and was paid only a small fee. Visit Notre Dame Cemetery respectfully from dawn to dusk.', 'limited', 'https://www.roadsideamerica.com/tip/58637', null, 'America/New_York', now()),
  ('Fort Independence', 'fort-independence', 'weird-history', 42.33799, -71.01095, 'Boston', 'MA', 'Five-pointed Fort Independence dominates Castle Island at the edge of Boston Harbor. The present granite fort dates largely to the nineteenth century, but military defenses have occupied the site since the 1600s. The surrounding park is open broadly; interior fort access depends on seasonal tours and events.', 'limited', 'https://www.atlasobscura.com/places/fort-independence', null, 'America/New_York', now()),
  ('Winnekenni Castle', 'winnekenni-castle', 'roadside-oddities', 42.78794, -71.06374, 'Haverhill', 'MA', 'A Victorian stone castle rises above Kenoza Lake inside Winnekenni Park. Built in the 1870s as a private summer retreat, it now serves as an event and community space while the surrounding trails remain public. Check ahead if seeing the interior matters.', 'limited', 'https://www.atlasobscura.com/places/winnekenni-castle', null, 'America/New_York', now()),
  ('Lake Chargoggagoggmanchauggagoggchaubunagungamaugg', 'lake-chargoggagoggmanchauggagoggchaubunagungamaugg', 'folklore', 42.0409, -71.8438, 'Webster', 'MA', 'Webster Lake is famous for an extraordinarily long alternate name that has become a Massachusetts roadside and linguistic curiosity. The famous spelling is modern and its supposed translation is often repeated inaccurately, but the giant name itself has become the attraction.', 'open', 'https://www.atlasobscura.com/places/lake-chargoggagoggmanchauggagoggchaubunagungamaugg', null, 'America/New_York', now()),
  ('Quincy Quarries', 'quincy-quarries', 'weird-history', 42.2444, -71.03421, 'Quincy', 'MA', 'Granite quarried here helped build major nineteenth-century structures, and the abandoned pits later became legendary among climbers and graffiti artists. Much of the old quarry landscape is now incorporated into public reservation land, where towering cut-stone walls remain visible.', 'open', 'https://www.atlasobscura.com/places/quincy-quarries-reservation', null, 'America/New_York', now()),
  ('Modica Way', 'modica-way', 'roadside-oddities', 42.36487, -71.10224, 'Cambridge', 'MA', 'A narrow Central Square passage has become a constantly changing legal graffiti gallery. One wall is regularly repainted by street artists, turning the alley into an artwork that may look completely different every time OddWay sends someone through.', 'open', 'https://www.atlasobscura.com/places/modica-way', null, 'America/New_York', now()),
  ('Madonna, Queen of the Universe', 'madonna-queen-of-the-universe', 'roadside-oddities', 42.39052, -71.00501, 'Boston', 'MA', 'A roughly 40-foot statue of Mary stands on a globe above East Boston, created in the 1950s by the Don Orione religious order. The oversized shrine is an unexpected landmark near Logan Airport and includes additional devotional spaces and religious objects.', 'open', 'https://www.atlasobscura.com/places/madonna-queen-of-the-universe', null, 'America/New_York', now()),
  ('Boston Tea Kettle', 'boston-tea-kettle', 'roadside-oddities', 42.3593, -71.05924, 'Boston', 'MA', 'A giant gilded kettle has hung above downtown Boston since the nineteenth century. It was originally installed as an advertising stunt, complete with a contest to guess how much liquid it could hold, and has survived as a rare piece of oversized Victorian commercial signage.', 'open', 'https://www.atlasobscura.com/places/boston-tea-kettle', null, 'America/New_York', now()),
  ('Bunker Hill Monument', 'bunker-hill-monument', 'weird-history', 42.37635, -71.06077, 'Boston', 'MA', 'A 221-foot granite obelisk marks the Revolutionary War Battle of Bunker Hill. The monument''s enormous interior staircase can be climbed when open, turning a familiar historical site into a surprisingly strenuous vertical stop.', 'limited', 'https://www.nps.gov/bost/learn/historyculture/bhm.htm', null, 'America/New_York', now()),
  ('Jaws Bridge', 'jaws-bridge', 'roadside-oddities', 41.41612, -70.54872, 'Edgartown', 'MA', 'The small bridge between Edgartown and Oak Bluffs became famous through Steven Spielberg''s ''Jaws.'' Fans still recognize it as the location of a shark-attack sequence, making an otherwise ordinary Martha''s Vineyard bridge a horror-film pilgrimage stop.', 'open', 'https://www.atlasobscura.com/places/jaws-bridge', null, 'America/New_York', now()),
  ('Boston History Dioramas', 'boston-history-dioramas', 'roadside-oddities', 42.35115, -71.07456, 'Boston', 'MA', 'Four elaborate historical dioramas hide inside the lobby of a Back Bay office building. The miniature scenes are easy to walk past from the street, making them a genuinely hidden bit of Boston history rather than a conventional museum exhibit.', 'limited', 'https://www.atlasobscura.com/places/boston-history-dioramas', null, 'America/New_York', now()),
  ('Jamaica Pond Bench', 'jamaica-pond-bench', 'roadside-oddities', 42.31701, -71.11719, 'Boston', 'MA', 'A professor secretly installed a U-shaped, two-backed bench beside Jamaica Pond as a guerrilla-art prank. Parks officials removed it, reconsidered, and ultimately allowed the strange seat to return, transforming unauthorized furniture into permanent public art.', 'open', 'https://www.atlasobscura.com/places/jamacia-pond-bench', null, 'America/New_York', now()),
  ('The Sacred Cod', 'the-sacred-cod', 'roadside-oddities', 42.35878, -71.06381, 'Boston', 'MA', 'A large carved wooden cod hangs inside the Massachusetts State House as a symbol of the fishing industry''s importance to the Commonwealth. The object has been stolen as a prank more than once, making it one of America''s stranger pieces of official government decor.', 'limited', 'https://www.atlasobscura.com/places/the-sacred-cod', null, 'America/New_York', now()),
  ('Site of Boston''s First Bell', 'site-of-bostons-first-bell', 'weird-history', 42.3637, -71.05369, 'Boston', 'MA', 'A small display at the Paul Revere House recalls the first bell cast in Boston by Paul Revere. Contemporary criticism suggested his earliest effort sounded rather bad, giving the celebrated craftsman a refreshingly imperfect first attempt.', 'open', 'https://www.atlasobscura.com/places/site-of-boston-s-first-bell', null, 'America/New_York', now()),
  ('Herb Mackey''s Metal Sculpture Yard', 'herb-mackeys-metal-sculpture-yard', 'roadside-oddities', 42.52299, -70.88239, 'Salem', 'MA', 'A Salem yard is crowded with creatures assembled from discarded metal, tools and machine parts. The handmade figures sit near the ferry route and turn a residential property into an evolving outsider-art menagerie. View respectfully from public space unless invited closer.', 'roadside', 'https://www.atlasobscura.com/places/herb-mackey-s-metal-sculpture-yard', null, 'America/New_York', now()),
  ('Purgatory Chasm', 'purgatory-chasm', 'roadside-oddities', 42.13634, -71.71776, 'Sutton', 'MA', 'A half-mile ravine slices through enormous blocks of granite, creating narrow passages, caves and overhangs with names that sound straight out of folklore. Glacial meltwater formed the chasm thousands of years ago; trail access can be restricted during hazardous winter conditions.', 'limited', 'https://www.atlasobscura.com/places/purgatory-chasm-2', null, 'America/New_York', now()),
  ('Harmonic Bridge', 'harmonic-bridge', 'roadside-oddities', 42.70093, -73.11374, 'North Adams', 'MA', 'Resonating tubes mounted beneath a highway overpass transform traffic vibration into a low, continuous musical drone. Instead of hiding road noise, artists Bruce Odland and Sam Auinger turned the bridge itself into a massive instrument.', 'open', 'https://www.atlasobscura.com/places/harmonic-bridge', null, 'America/New_York', now()),
  ('Skull Cliff', 'skull-cliff', 'roadside-oddities', 42.51127, -71.00806, 'Lynnfield', 'MA', 'A large skull face peers from an exposed rock wall beside the road. The painted or carved-looking feature has become a local visual landmark that makes an otherwise ordinary stretch of stone suddenly resemble a giant human head.', 'roadside', 'https://www.atlasobscura.com/places/skull-cliff', null, 'America/New_York', now()),
  ('The Rock and Fossil and Dinosaur Shop', 'the-rock-and-fossil-and-dinosaur-shop', 'roadside-oddities', 42.50012, -72.60924, 'Deerfield', 'MA', 'A roadside geology shop surrounds visitors with dinosaur replicas, fossils, minerals and a backyard ''Dinosaur Forest'' that even includes a UFO-and-alien scene. It is part educational rock shop and part old-school roadside attraction.', 'limited', 'https://www.atlasobscura.com/places/the-rock-and-fossil-and-dinosaur-shop-deerfield-massachusetts', null, 'America/New_York', now()),
  ('Eric Carle Museum of Picture Book Art', 'eric-carle-museum-of-picture-book-art', 'museums', 42.32109, -72.53298, 'Amherst', 'MA', 'A museum devoted specifically to picture-book illustration celebrates the visual worlds of Eric Carle and other children''s artists. Rotating exhibits expose original artwork and process material normally hidden behind familiar printed books.', 'limited', 'https://www.carlemuseum.org/', null, 'America/New_York', now()),
  ('Mount Auburn Cemetery', 'mount-auburn-cemetery', 'weird-history', 42.3709, -71.14634, 'Cambridge', 'MA', 'America''s first large landscaped rural cemetery mixes elaborate monuments, mausoleums, unusual funerary sculpture, ponds and a hilltop tower across more than 170 acres. It helped change American ideas about what a cemetery could look like.', 'open', 'https://www.mountauburn.org/', null, 'America/New_York', now()),
  ('The Oozing Whale Skeleton of New Bedford', 'the-oozing-whale-skeleton-of-new-bedford', 'museums', 41.63547, -70.9231, 'New Bedford', 'MA', 'A huge blue whale skeleton called KOBO hangs in the New Bedford Whaling Museum and famously continued leaking natural oil for years after preparation. The massive bones are surrounded by one of the country''s most extensive whaling collections.', 'limited', 'https://www.atlasobscura.com/places/the-oozing-whale-skeleton-of-new-bedford-new-bedford-massachusetts', null, 'America/New_York', now()),
  ('Potato Shed Memorial', 'potato-shed-memorial', 'roadside-oddities', 42.37195, -71.06575, 'Boston', 'MA', 'A stack of stone potato sacks marks the site of Charlestown''s old railroad potato sheds, destroyed by fire in 1962. The deliberately mundane sculpture memorializes a vanished industrial landscape with one of Boston''s strangest monuments.', 'open', 'https://www.atlasobscura.com/places/potato-shed-memorial', null, 'America/New_York', now()),
  ('Exchange Place Staircase to Nowhere', 'exchange-place-staircase-to-nowhere', 'roadside-oddities', 42.35851, -71.05618, 'Boston', 'MA', 'An ornate nineteenth-century staircase survives inside a modern office tower even though the building it once served is gone. The preserved steps rise dramatically into contemporary space, looking like a grand staircase disconnected from its original world.', 'limited', 'https://www.atlasobscura.com/places/exchange-place-staircase-to-nowhere', null, 'America/New_York', now()),
  ('North End Street Utensils', 'north-end-street-utensils', 'roadside-oddities', 42.36297, -71.05644, 'Boston', 'MA', 'Actual knives and forks are embedded in sidewalks outside Italian food businesses in Boston''s North End. The easy-to-miss cutlery reflects an old visual tradition of identifying food shops and rewards travelers who remember to look down.', 'open', 'https://www.atlasobscura.com/places/north-end-street-utensils', null, 'America/New_York', now()),
  ('Jack Kerouac''s Grave', 'jack-kerouacs-grave', 'weird-history', 42.61808, -71.30747, 'Lowell', 'MA', 'Beat writer Jack Kerouac rests beneath an understated flat marker in Lowell''s Edson Cemetery. Admirers have traditionally left pens, cigarettes, notes and other offerings at the grave. Visit only during cemetery hours and leave the site undisturbed.', 'limited', 'https://www.atlasobscura.com/places/jack-kerouacs-grave', null, 'America/New_York', now()),
  ('Borderland State Park Mansion', 'borderland-state-park-mansion', 'roadside-oddities', 42.06561, -71.1092, 'Easton', 'MA', 'A stone mansion built for eccentric botanist Oakes Ames and artist Blanche Ames stands amid the unusual landscaped estate that became Borderland State Park. Blanche designed much of the house herself and filled the property with artistic and scientific experimentation.', 'limited', 'https://www.atlasobscura.com/places/borderland-state-park', null, 'America/New_York', now()),
  ('Aquinnah Cliffs', 'aquinnah-cliffs', 'folklore', 41.34758, -70.8376, 'Aquinnah', 'MA', 'Multicolored clay cliffs rise above Martha''s Vineyard at a place sacred to the Wampanoag people and connected with stories of the giant Moshup. The cliffs are both a dramatic geological formation and an important Indigenous cultural landscape; removing clay is prohibited.', 'open', 'https://www.atlasobscura.com/places/aquinnah-cliffs', null, 'America/New_York', now()),
  ('Paul Revere Lantern', 'paul-revere-lantern', 'weird-history', 42.45771, -71.34226, 'Concord', 'MA', 'The Concord Museum preserves one of the original lanterns associated with the ''one if by land, two if by sea'' signal from Old North Church on April 18, 1775. It is a small physical object tied to one of America''s most famous historical warnings.', 'limited', 'https://www.atlasobscura.com/places/paul-revere-lantern', null, 'America/New_York', now()),
  ('Poet''s Seat Tower', 'poets-seat-tower', 'roadside-oddities', 42.5946, -72.5865, 'Greenfield', 'MA', 'A stone observation tower crowns Rocky Mountain above Greenfield. Its name recalls nineteenth-century writers who gathered on the hill, while the current tower gives the wooded summit the look of a miniature medieval fortification.', 'limited', 'https://www.atlasobscura.com/places/poets-seat-tower', null, 'America/New_York', now()),
  ('Hut of Refuge', 'hut-of-refuge', 'weird-history', 42.32584, -70.92557, 'Hull', 'MA', 'A small lifesaving shelter survives on isolated Peddocks Island from the era when shipwreck survivors needed emergency refuge along Boston Harbor. Reaching it requires seasonal island access, making the journey part of the stop.', 'limited', 'https://www.atlasobscura.com/places/hut-of-refuge', null, 'America/New_York', now()),
  ('Fort Standish', 'fort-standish', 'weird-history', 42.32981, -70.92765, 'Hull', 'MA', 'Overgrown coastal-defense ruins sprawl across Peddocks Island, including concrete batteries and abandoned military structures from the harbor''s defensive network. The island is reached seasonally; closed structures and unsafe interiors should not be entered.', 'limited', 'https://www.atlasobscura.com/places/fort-standish', null, 'America/New_York', now()),
  ('Lyceum Hall', 'lyceum-hall', 'weird-history', 42.52243, -70.89519, 'Salem', 'MA', 'Alexander Graham Bell demonstrated a successful long-distance telephone call from Salem''s Lyceum Hall in 1877. The original building has changed uses, but the location preserves an unexpectedly important milestone in communications history amid downtown Salem.', 'open', 'https://www.atlasobscura.com/places/lyceum-hall', null, 'America/New_York', now()),
  ('Martini Junction', 'martini-junction', 'roadside-oddities', 42.26898, -71.24728, 'Needham', 'MA', 'A tiny railroad junction complete with miniature signs appears along a wooded trail, built around a small-scale railway installation. The unexpected infrastructure feels like stumbling across a functioning transportation system for woodland creatures.', 'open', 'https://www.atlasobscura.com/places/martini-junction', null, 'America/New_York', now()),
  ('New England Peace Pagoda', 'new-england-peace-pagoda', 'roadside-oddities', 42.49896, -72.49116, 'Leverett', 'MA', 'A gleaming white Buddhist peace pagoda rises from rural western Massachusetts, one of the first structures of its kind built in the United States. The grounds include shrines, gardens and spaces intended for quiet reflection.', 'open', 'https://www.atlasobscura.com/places/new-england-peace-pagoda', null, 'America/New_York', now()),
  ('The Witches of Eastwick Filming Sites', 'the-witches-of-eastwick-filming-sites', 'roadside-oddities', 42.2426, -70.80339, 'Cohasset', 'MA', 'Several locations around Cohasset stood in for the fictional New England town in the 1987 supernatural comedy ''The Witches of Eastwick.'' The compact town center makes it possible to connect real streets and buildings with the film''s witchy setting.', 'open', 'https://www.atlasobscura.com/places/the-witches-of-eastwick-filming-sites', null, 'America/New_York', now()),
  ('Ether Monument', 'ether-monument', 'weird-history', 42.35482, -71.07143, 'Boston', 'MA', 'A dramatic monument in Boston Public Garden commemorates the introduction of surgical anesthesia. The sculpture is unusually elaborate for a medical breakthrough, combining allegorical figures and biblical imagery around a discovery that transformed surgery.', 'open', 'https://www.atlasobscura.com/places/ether-monument', null, 'America/New_York', now()),
  ('Charles River Museum of Industry and Innovation', 'charles-river-museum-of-industry-and-innovation', 'museums', 42.37319, -71.23369, 'Waltham', 'MA', 'Inside the former Boston Manufacturing Company complex, machinery and artifacts trace the transition from hand production to industrial manufacturing. The museum occupies a birthplace of America''s factory system, with large mechanical objects filling the old mill space.', 'limited', 'https://www.charlesrivermuseum.org/', null, 'America/New_York', now()),
  ('High Rock Tower', 'high-rock-tower', 'roadside-oddities', 42.46802, -70.94647, 'Lynn', 'MA', 'A stone observatory tower rises high above Lynn from a hill long associated with astronomy and nineteenth-century Spiritualist experiments. The exterior grounds are accessible, while interior observatory access depends on scheduled public programs.', 'limited', 'https://www.atlasobscura.com/places/high-rock-tower', null, 'America/New_York', now()),
  ('Black Veil Shoppe of Drear & Wonder', 'black-veil-shoppe-of-drear-wonder', 'roadside-oddities', 42.52154, -70.91475, 'Salem', 'MA', 'A darkly theatrical Salem shop from twin artists Matt and Ryan Murray combines macabre artwork, apparel, curiosities and an immersive gothic interior. It is a contemporary oddities stop rather than a witch-trial site.', 'open', 'https://www.blackveilshoppe.com/', null, 'America/New_York', now()),
  ('Salem Witch Board Museum', 'salem-witch-board-museum', 'museums', 42.52222, -70.89089, 'Salem', 'MA', 'A small museum explores Ouija boards, spirit communication and talking-board history through vintage boards and related objects. It gives Salem a paranormal stop centered on Spiritualism and commercial occult culture rather than the 1692 trials.', 'limited', 'https://www.atlasobscura.com/places/salem-witch-board-museum', null, 'America/New_York', now()),
  ('Ye Olde Pepper Candy Companie', 'ye-olde-pepper-candy-companie', 'weird-history', 42.5225, -70.88476, 'Salem', 'MA', 'One of America''s oldest candy companies still sells old-fashioned sweets near the House of the Seven Gables. Its famous Gibralters and Black Jacks preserve recipes and candy traditions reaching back to the early nineteenth century.', 'open', 'https://www.atlasobscura.com/places/ye-olde-pepper-candy-companie', null, 'America/New_York', now()),
  ('The Daniels House', 'the-daniels-house', 'roadside-oddities', 42.52297, -70.88682, 'Salem', 'MA', 'A remarkably old First Period house dating to the seventeenth century now operates as an inn and tour location. Its uneven rooms, massive fireplaces and centuries of alterations provide a much more intimate experience of old Salem than a reconstructed attraction.', 'limited', 'https://www.atlasobscura.com/places/the-daniels-house', null, 'America/New_York', now()),
  ('Schooner Fame of Salem', 'schooner-fame-of-salem', 'weird-history', 42.51964, -70.88806, 'Salem', 'MA', 'A working replica of the War of 1812 privateer Fame sails from Salem Harbor. The original ship captured multiple vessels before being lost, while the modern schooner gives visitors a rare chance to experience Salem''s privateering history under sail.', 'limited', 'https://schoonerfame.com/', null, 'America/New_York', now()),
  ('Yin Yu Tang: A Chinese Home', 'yin-yu-tang-a-chinese-home', 'roadside-oddities', 42.52211, -70.89289, 'Salem', 'MA', 'An entire late-Qing-dynasty merchant family''s house was dismantled in China, shipped to Massachusetts and reconstructed inside the Peabody Essex Museum complex. The furnished house preserves generations of domestic architecture in an extraordinary transplanted setting.', 'limited', 'https://www.pem.org/yin-yu-tang-a-chinese-home', null, 'America/New_York', now()),
  ('First Spiritualist Temple', 'first-spiritualist-temple', 'haunted', 42.35058, -71.07986, 'Boston', 'MA', 'A Romanesque building in Back Bay was constructed for a Spiritualist congregation during the movement''s nineteenth-century boom. Its history reflects the period when séances, spirit communication and Spiritualism became organized religious practices in New England.', 'roadside', 'https://www.atlasobscura.com/places/first-spiritualist-temple', null, 'America/New_York', now()),
  ('Dr. Seuss Sculpture Garden', 'dr-seuss-sculpture-garden', 'roadside-oddities', 42.10455, -72.58731, 'Springfield', 'MA', 'Bronze versions of the Cat in the Hat, Horton, the Grinch and other Dr. Seuss characters surround a sculpture of Springfield-born author Theodor Geisel. The outdoor garden turns his illustrated universe into a walkable cluster of oversized characters.', 'open', 'https://springfieldmuseums.org/about/dr-seuss-sculpture-garden/', null, 'America/New_York', now()),
  ('Natural Bridge State Park', 'natural-bridge-state-park', 'roadside-oddities', 42.70675, -73.09288, 'North Adams', 'MA', 'A natural white-marble arch spans a rushing brook inside the remains of an old marble quarry. The unusual combination of natural bridge, carved marble gorge and industrial quarry history makes this one of western Massachusetts'' strongest geology stops.', 'limited', 'https://www.mass.gov/locations/natural-bridge-state-park', null, 'America/New_York', now()),
  ('Skinny House', 'skinny-house', 'roadside-oddities', 42.36691, -71.0562, 'Boston', 'MA', 'Boston''s famously narrow ''spite house'' squeezes into a tiny North End lot. Local tradition says one brother built it to block another brother''s view after a property dispute, although details of the story vary. It remains a private residence.', 'roadside', 'https://www.atlasobscura.com/places/skinny-house', null, 'America/New_York', now()),
  ('All Saints Way', 'all-saints-way', 'folklore', 42.36634, -71.0525, 'Boston', 'MA', 'A narrow North End alley has been transformed by one resident into a dense devotional display of saint statues, holy cards, lights and Catholic imagery. The collection sits on private property but is often visible from the entrance; access depends on the owner''s availability.', 'limited', 'https://www.atlasobscura.com/places/all-saints-way', null, 'America/New_York', now()),
  ('Spectacle Island Sea Glass Beaches', 'spectacle-island-sea-glass-beaches', 'weird-history', 42.3224, -70.9877, 'Boston', 'MA', 'Boston Harbor''s former garbage dump was capped and remade into Spectacle Island, but its beaches still reveal colorful sea glass, ceramics and fragments of the city''s discarded past. Park rules require visitors to leave these cultural materials where they find them. Ferry access is seasonal.', 'limited', 'https://www.atlasobscura.com/places/spectacle-island', null, 'America/New_York', now()),
  ('Montague Bookmill', 'montague-bookmill', 'roadside-oddities', 42.5378, -72.5389, 'Montague', 'MA', 'A used-book store fills a nineteenth-century gristmill beside the rushing Sawmill River. Its famously fatalistic slogan — ''Books you don''t need in a place you can''t find'' — fits the maze of shelves, old machinery and riverside rooms.', 'open', 'https://www.montaguebookmill.com/', null, 'America/New_York', now()),
  ('Necco Wafer Sculpture', 'necco-wafer-sculpture', 'roadside-oddities', 42.36198, -71.10129, 'Cambridge', 'MA', 'Metal Necco wafers appear to spill from a crumpled candy bag onto a boulder near the site of the former New England Confectionery Company factory. The tiny sculpture preserves a candy-making history that once filled this part of Cambridge with sugar and peppermint smells.', 'open', 'https://www.atlasobscura.com/places/necco-wafer-sculpture', null, 'America/New_York', now()),
  ('Billingsgate Island', 'billingsgate-island', 'weird-history', 41.8684, -70.0659, 'Eastham', 'MA', 'A once-inhabited Cape Cod island with a lighthouse, homes and fishing community was gradually erased by erosion until it slipped beneath the water. At very low tides parts of the former island can reappear, but currents, tides and offshore access make this a view-or-boat-history stop rather than a casual walk.', 'roadside', 'https://www.atlasobscura.com/places/billingsgate-island', null, 'America/New_York', now()),
  ('Bell Ringing Chamber at Old North Church', 'bell-ringing-chamber-at-old-north-church', 'weird-history', 42.36634, -71.05443, 'Boston', 'MA', 'High inside Old North Church is the chamber containing the oldest set of change-ringing bells in North America. Paul Revere was among the early ringers, and scheduled tours climb into the tower to explain the highly mathematical ringing tradition.', 'limited', 'https://www.atlasobscura.com/places/bell-ringing-chamber-at-old-north-church', null, 'America/New_York', now()),
  ('Diorama of Venetian Palace', 'diorama-of-venetian-palace', 'roadside-oddities', 42.34931, -71.07824, 'Boston', 'MA', 'A painstaking miniature Venetian palace scene is tucked inside the Boston Public Library''s McKim Building. The architectural model grew out of one collector''s obsession with recreating an ornate European interior in tiny scale.', 'limited', 'https://www.atlasobscura.com/places/diorama-of-venetian-palace', null, 'America/New_York', now()),
  ('Gunnar Schonbeck Exhibit', 'gunnar-schonbeck-exhibit', 'roadside-oddities', 42.70187, -73.11519, 'North Adams', 'MA', 'More than 200 wildly unconventional instruments at MASS MoCA include a nine-foot banjo, aircraft-fuselage drums and giant sound towers. Visitors are encouraged to play many of them, fulfilling artist Gunnar Schonbeck''s belief that everyone can make music.', 'limited', 'https://www.atlasobscura.com/places/no-experience-required', null, 'America/New_York', now()),
  ('Harvard Divinity School Labyrinth', 'harvard-divinity-school-labyrinth', 'folklore', 42.38043, -71.11361, 'Cambridge', 'MA', 'A small Chartres-inspired labyrinth is laid into a quiet Harvard Divinity School courtyard. The many-turning path is meant for slow contemplative walking and creates a hidden meditative space within the university campus.', 'open', 'https://www.atlasobscura.com/places/harvard-divinity-school-labyrinth', null, 'America/New_York', now()),
  ('Old Powder House', 'old-powder-house', 'weird-history', 42.40007, -71.11622, 'Somerville', 'MA', 'A squat stone tower built around 1703 began as a windmill before becoming a colonial gunpowder magazine. Its stored powder played a role in rising tensions before the American Revolution, and the lonely tower now sits inside a public neighborhood park.', 'open', 'https://www.atlasobscura.com/places/old-powder-house', null, 'America/New_York', now()),
  ('Herreshoff Castle', 'herreshoff-castle', 'roadside-oddities', 42.5035, -70.84886, 'Marblehead', 'MA', 'A 1920 stone castle inspired by Viking-era Greenland hides in Marblehead, complete with turrets and Gothic windows. Legends mention secret stairs and buried treasure, though those stories are unproven. The property has operated as lodging and is not a free-roaming public ruin.', 'limited', 'https://www.atlasobscura.com/places/herreshoff-castle', null, 'America/New_York', now()),
  ('Eunice Williams Covered Bridge', 'eunice-williams-covered-bridge', 'folklore', 42.64654, -72.62018, 'Greenfield', 'MA', 'A covered bridge crosses the Green River near the place where Eunice Williams was killed during the 1704 Deerfield raid. Local ghost lore claims her apparition still appears near the bridge, especially on moonless nights. The haunting is folklore layered onto a documented historical tragedy.', 'open', 'https://www.atlasobscura.com/places/eunice-williams-covered-bridge', null, 'America/New_York', now()),
  ('Ford''s Folly', 'fords-folly', 'weird-history', 42.35418, -71.46019, 'Sudbury', 'MA', 'Automobile magnate Henry Ford attempted to build a dam near the Wayside Inn, only for the expensive project to fail at holding water as intended. The surviving stonework is a monument to an unusually literal piece of engineering folly.', 'open', 'https://www.atlasobscura.com/places/fords-folly', null, 'America/New_York', now()),
  ('The Dutch House', 'the-dutch-house', 'roadside-oddities', 42.33581, -71.11228, 'Brookline', 'MA', 'A convincing Dutch Renaissance-style building sits among Brookline homes because it was originally constructed as a cocoa-company pavilion for the 1893 World''s Columbian Exposition in Chicago, then moved east. It remains private property and should be viewed only from public space.', 'private', 'https://www.atlasobscura.com/places/the-dutch-house', null, 'America/New_York', now()),
  ('The Spruces', 'the-spruces', 'weird-history', 42.70238, -73.17832, 'Williamstown', 'MA', 'A former mobile-home community devastated by flooding was cleared and transformed into a public park. Roads, plantings and other subtle traces of the vanished neighborhood remain, giving the open landscape the feel of a community erased without being completely forgotten.', 'open', 'https://www.atlasobscura.com/places/the-spruces', null, 'America/New_York', now()),
  ('Joshua Ward House', 'joshua-ward-house', 'haunted', 42.5204, -70.89595, 'Salem', 'MA', 'The Merchant hotel occupies the eighteenth-century Joshua Ward House, built on land once associated with Salem sheriff George Corwin. George Washington later stayed here. Ghost stories have accumulated around the property, but it remains an operating hotel rather than a paranormal attraction.', 'limited', 'https://www.atlasobscura.com/places/joshua-ward-house', null, 'America/New_York', now()),
  ('Nantucket Whaling Museum', 'nantucket-whaling-museum', 'museums', 41.28553, -70.09891, 'Nantucket', 'MA', 'A massive sperm-whale skeleton hangs over a museum devoted to Nantucket''s whaling era. Scrimshaw, ship material and maritime artifacts tell the darker industrial history behind the island''s picturesque image.', 'limited', 'https://nha.org/visit/museums-and-tours/whaling-museum/', null, 'America/New_York', now()),
  ('Pooh''s House', 'poohs-house', 'roadside-oddities', 42.3763, -71.1166, 'Cambridge', 'MA', 'A miniature painted door at the base of a tree on Harvard''s campus has long been treated as the home of Winnie-the-Pooh. The tiny installation has been repaired and recreated over the years, turning an ordinary stump into a persistent campus folk-art landmark.', 'open', 'https://www.atlasobscura.com/places/poohs-house', null, 'America/New_York', now()),
  ('Georges Island and Fort Warren', 'georges-island-and-fort-warren', 'weird-history', 42.32032, -70.92751, 'Boston', 'MA', 'Fort Warren occupies much of Georges Island in Boston Harbor, with granite corridors, casemates and defensive works open to explore during the ferry season. The fort is also tied to the legend of the Lady in Black, one of Boston Harbor''s best-known ghost stories.', 'limited', 'https://www.bostonharborislands.org/georges-island/', null, 'America/New_York', now()),
  ('Cape Cinema', 'cape-cinema', 'roadside-oddities', 41.74034, -70.19346, 'Dennis', 'MA', 'A 1930 movie theater hides an enormous Rockwell Kent mural across its curved ceiling, filled with constellations, floating figures and celestial imagery. Moviegoers often find the ceiling as memorable as whatever is playing on the screen.', 'limited', 'https://www.atlasobscura.com/places/cape-cinema', null, 'America/New_York', now()),
  ('American Antiquarian Society', 'american-antiquarian-society', 'museums', 42.27724, -71.81034, 'Worcester', 'MA', 'One of the nation''s great collections of early American printed material preserves newspapers, books, broadsides and ephemera reaching back centuries. Exhibits and public programs expose strange fragments of everyday history that usually remain inside research archives.', 'limited', 'https://www.americanantiquarian.org/', null, 'America/New_York', now()),
  ('The Mushroom Shop', 'the-mushroom-shop', 'roadside-oddities', 42.39251, -71.10038, 'Somerville', 'MA', 'A shop devoted almost entirely to fungi sells unusual edible mushrooms, cultivation kits, tinctures, books and mushroom-themed objects. It functions as a small mycological gallery and community hub for people fascinated by the hidden world of fungi.', 'open', 'https://www.atlasobscura.com/places/the-mushroom-shop', null, 'America/New_York', now()),
  ('Simpson Spring', 'simpson-spring', 'weird-history', 42.03728, -71.07933, 'Easton', 'MA', 'An independent bottling plant operating over a natural spring since the nineteenth century still produces old-fashioned sodas and lets visitors fill water jugs from the source. The property preserves vintage equipment and a stubbornly old-school soda-making tradition.', 'open', 'https://www.atlasobscura.com/places/simpson-spring', null, 'America/New_York', now()),
  ('Gates of the City — Portas da Cidade', 'gates-of-the-city-portas-da-cidade', 'roadside-oddities', 41.70055, -71.16583, 'Fall River', 'MA', 'A 60-foot replica of the famous city gates of Ponta Delgada in the Azores rises beside Fall River''s waterfront. The monument honors the city''s large Portuguese and Azorean community and looks startlingly monumental beside modern streets.', 'open', 'https://www.atlasobscura.com/places/gates-of-the-city-or-portas-da-cidade', null, 'America/New_York', now()),
  ('Red Auerbach Good Luck Plaque', 'red-auerbach-good-luck-plaque', 'folklore', 42.36647, -71.06189, 'Boston', 'MA', 'A shamrock-shaped plaque inside North Station invites travelers to touch it for good luck in honor of legendary Celtics coach and executive Red Auerbach. Years of hands have turned an ordinary commemorative plaque into an interactive sports ritual.', 'open', 'https://www.atlasobscura.com/places/red-auerbach-good-luck-plaque', null, 'America/New_York', now()),
  ('Fook C. Kan Plaque', 'fook-c-kan-plaque', 'folklore', 42.3523, -71.0553, 'Boston', 'MA', 'A memorial plaque dedicated to carpenter Fook C. Kan contains puzzling errors and inconsistencies that have made its exact backstory difficult to untangle. The modest marker is a small urban mystery hidden in plain sight.', 'open', 'https://www.atlasobscura.com/places/fook-c-kan-plaque', null, 'America/New_York', now()),
  ('''Glove Cycle''', 'glove-cycle', 'roadside-oddities', 42.3884, -71.1191, 'Cambridge', 'MA', 'Dozens of bronze gloves are scattered through Porter Square station as if lost by generations of commuters. The installation turns one of the most commonly misplaced winter objects in New England into a permanent underground art cycle.', 'open', 'https://www.atlasobscura.com/places/glove-cycle', null, 'America/New_York', now()),
  ('King Bhumibol Adulyadej Birthplace Marker', 'king-bhumibol-adulyadej-birthplace-marker', 'weird-history', 42.3723, -71.122, 'Cambridge', 'MA', 'A plaque marks the Cambridge birthplace of Thailand''s King Bhumibol Adulyadej, born while his father studied at Harvard. The future monarch would become one of the longest-reigning sovereigns in modern history.', 'open', 'https://www.atlasobscura.com/places/king-bhumibol-adulyadej-birthplace-marker', null, 'America/New_York', now()),
  ('George''s Coney Island', 'georges-coney-island', 'weird-history', 42.2576, -71.804, 'Worcester', 'MA', 'A century-old hot-dog institution preserves a vintage Art Deco interior and the local tradition of Coney Island-style dogs. The neon, stools and old signage make the restaurant feel like a still-functioning piece of roadside food history.', 'open', 'https://www.atlasobscura.com/places/georges-coney-island', null, 'America/New_York', now()),
  ('Siege of Brookfield Historic Markers', 'siege-of-brookfield-historic-markers', 'weird-history', 42.34328, -72.1428, 'New Braintree', 'MA', 'Several lonely roadside stones mark locations connected with the 1675 Siege of Brookfield during King Philip''s War, including an ambush and a camp associated with Metacomet. The markers preserve a violent chapter of colonial and Indigenous history that is otherwise easy to drive past.', 'roadside', 'https://www.atlasobscura.com/places/siege-of-brookfield-historic-markers', null, 'America/New_York', now()),
  ('Marathon Park', 'marathon-park', 'weird-history', 42.26266, -71.47881, 'Ashland', 'MA', 'Before the Boston Marathon starting line moved to Hopkinton, early races began in Ashland. This small park preserves the original starting area with markers and displays tied to the world''s oldest annual marathon.', 'open', 'https://www.atlasobscura.com/places/marathon-park', null, 'America/New_York', now()),
  ('Boston Athenaeum Skin Book', 'boston-athenaeum-skin-book', 'museums', 42.35808, -71.06234, 'Boston', 'MA', 'The Boston Athenaeum holds the memoir of highwayman James Allen, historically described as being bound in his own skin at his request. Conservation concerns mean the book is no longer permanently displayed, so the stop is the library and its morbid collection history rather than guaranteed viewing of the object.', 'limited', 'https://www.atlasobscura.com/places/boston-athenaeum-skin-book', null, 'America/New_York', now()),
  ('Empire Garden Restaurant', 'empire-garden-restaurant', 'roadside-oddities', 42.3515, -71.0628, 'Boston', 'MA', 'A cavernous Chinatown restaurant occupies the former Globe Theatre, leaving diners surrounded by balconies, ornate plasterwork and remnants of a grand performance hall while eating dim sum.', 'open', 'https://www.atlasobscura.com/places/empire-garden-restaurant', null, 'America/New_York', now()),
  ('Ruins of Schoolmaster Hill', 'ruins-of-schoolmaster-hill', 'weird-history', 42.30305, -71.09572, 'Boston', 'MA', 'Stone walls and terraces remain from an Olmsted-designed Franklin Park structure that once served visitors and later golfers. Fire reduced the building to a scenic ruin on the same hill where Ralph Waldo Emerson had lived decades earlier.', 'open', 'https://www.atlasobscura.com/places/ruins-of-schoolmaster-hill', null, 'America/New_York', now()),
  ('Boston''s Old Burying Grounds', 'bostons-old-burying-grounds', 'weird-history', 42.3573, -71.0613, 'Boston', 'MA', 'Boston''s oldest downtown graveyards are filled with winged skulls, hourglasses, skeletons and other stark Puritan mortality symbols. A walk through the historic burying grounds becomes an outdoor gallery of macabre colonial stone carving.', 'open', 'https://www.atlasobscura.com/places/bostons-old-burying-grounds', null, 'America/New_York', now()),
  ('Caffe Vittoria', 'caffe-vittoria', 'roadside-oddities', 42.364, -71.0543, 'Boston', 'MA', 'Boston''s oldest Italian café doubles as a museum of vintage espresso machines, coffee equipment and old advertising. The dense collection gives a cup of coffee the surroundings of an accidental technology museum.', 'open', 'https://www.atlasobscura.com/places/caffe-vittoria', null, 'America/New_York', now()),
  ('Bash Bish Falls', 'bash-bish-falls', 'folklore', 42.11481, -73.4929, 'Mount Washington', 'MA', 'Massachusetts'' largest waterfall drops through a dramatic Berkshire gorge with a long history of fatal accidents and local legends. Current restrictions prohibit access to the plunge pool and lower area, so visitors must obey barriers and use designated overlooks.', 'limited', 'https://www.atlasobscura.com/places/bash-bish-falls', null, 'America/New_York', now()),
  ('Singing Beach', 'singing-beach', 'roadside-oddities', 42.57058, -70.76065, 'Manchester-by-the-Sea', 'MA', 'Under the right dry conditions, shuffling across this beach produces a distinct squeak or ''singing'' sound as similarly sized sand grains rub together. Summer parking and access are tightly controlled, so check current municipal rules before routing here.', 'limited', 'https://www.atlasobscura.com/places/singing-beach-at-manchester-by-the-sea', null, 'America/New_York', now()),
  ('Museum of Modern Renaissance', 'museum-of-modern-renaissance', 'roadside-oddities', 42.39991, -71.11803, 'Somerville', 'MA', 'Two artists transformed a former Masonic hall into a floor-to-ceiling ''Temple of Art'' covered with mythological figures, geometric patterns and intensely colored murals. Public access is event-based or arranged rather than conventional daily museum hours.', 'limited', 'https://www.atlasobscura.com/places/museum-of-modern-renaissance', null, 'America/New_York', now()),
  ('First Dunkin'' Donuts', 'first-dunkin-donuts', 'weird-history', 42.2529, -70.99293, 'Quincy', 'MA', 'The first Dunkin'' Donuts still operates at the site where William Rosenberg renamed his earlier Open Kettle shop in 1950. The modern store includes retro decor and displays recalling the chain''s beginnings.', 'open', 'https://www.atlasobscura.com/places/first-dunkin-donuts', null, 'America/New_York', now()),
  ('Shunpike', 'shunpike', 'weird-history', 42.63604, -72.90576, 'Charlemont', 'MA', 'A Mohawk Trail rest area marks the place where travelers historically forded the Deerfield River to avoid paying a turnpike toll. The act helped popularize the term ''shunpike'' for deliberately bypassing toll roads.', 'roadside', 'https://www.atlasobscura.com/places/shunpike', null, 'America/New_York', now()),
  ('Keystone Arch Bridges', 'keystone-arch-bridges', 'weird-history', 42.31158, -72.99261, 'Chester', 'MA', 'A woodland trail reaches enormous dry-laid stone railroad arches built in the nineteenth century without mortar. Some rise more than 70 feet and survive as monumental remnants of early American railroad engineering.', 'open', 'https://www.atlasobscura.com/places/keystone-arch-bridges', null, 'America/New_York', now()),
  ('Quentin Compson Memorial', 'quentin-compson-memorial', 'roadside-oddities', 42.36896, -71.1232, 'Boston', 'MA', 'A tiny brass plaque on Anderson Memorial Bridge commemorates the fictional suicide of William Faulkner character Quentin Compson as if he were a real person. Literature has been quietly inserted into Boston''s physical landscape.', 'open', 'https://www.atlasobscura.com/places/quentin-compson-memorial', null, 'America/New_York', now()),
  ('Harvard Bridge Smoot Measurements', 'harvard-bridge-smoot-measurements', 'roadside-oddities', 42.35474, -71.09141, 'Boston', 'MA', 'Painted marks across Harvard Bridge measure its length in ''smoots,'' a unit created in 1958 by repeatedly laying MIT pledge Oliver Smoot end to end. The final measurement — 364.4 smoots plus one ear — became a lasting engineering-school joke.', 'open', 'https://www.atlasobscura.com/places/harvard-bridge-smoot-measurements', null, 'America/New_York', now()),
  ('Stone''s Bridge', 'stones-bridge', 'weird-history', 42.33917, -71.39541, 'Framingham', 'MA', 'A dry-laid stone bridge from the 1850s extends partway across the Sudbury River after flood damage removed one approach. The structure is stabilized but closed to crossing, leaving a historic bridge that quite literally leads nowhere.', 'roadside', 'https://www.atlasobscura.com/places/stones-bridge', null, 'America/New_York', now()),
  ('Hillside Cemetery', 'hillside-cemetery', 'weird-history', 42.70089, -73.12115, 'North Adams', 'MA', 'This eighteenth-century cemetery is filled with unusually sculptural monuments, including tree-shaped stones and the elaborate Tinker Mausoleum. It functions almost like an outdoor art museum despite having few nationally famous burials.', 'limited', 'https://www.atlasobscura.com/places/hillside-cemetery', null, 'America/New_York', now()),
  ('Graves of John Cloyce & Abraham Rice', 'graves-of-john-cloyce-abraham-rice', 'weird-history', 42.2976, -71.4286, 'Framingham', 'MA', 'Two men killed by the same lightning strike in 1777 are remembered with neighboring stones. The paired graves preserve the bizarre shared fate of John Cloyce and Abraham Rice inside Framingham''s historic burial landscape.', 'limited', 'https://www.atlasobscura.com/places/graves-of-john-cloyce-abraham-rice', null, 'America/New_York', now()),
  ('Learned Pond — Captain Kidd Treasure Legend', 'learned-pond-captain-kidd-treasure-legend', 'folklore', 42.28705, -71.41864, 'Framingham', 'MA', 'Local legend claims pirate William Kidd buried treasure around this otherwise ordinary pond. Historical evidence for Kidd visiting the spot is weak, though another pirate connected with him had regional ties, leaving a durable Massachusetts treasure story.', 'open', 'https://www.atlasobscura.com/places/learned-pond-farmingham-massachusetts', null, 'America/New_York', now()),
  ('Sarah Clayes House', 'sarah-clayes-house', 'weird-history', 42.28722, -71.46303, 'Framingham', 'MA', 'This early house is associated with Sarah Clayes, who survived accusations during the Salem witch trials and later settled in the area known as Salem End. The restored building is a private residence, so view only from lawful public space.', 'private', 'https://www.atlasobscura.com/places/sarah-clayes-house', null, 'America/New_York', now()),
  ('Omiskanoagwiah', 'omiskanoagwiah', 'roadside-oddities', 42.07268, -72.58171, 'Springfield', 'MA', 'A 15-foot wooden head carved by Peter Wolf Toth stands at the Route 5 entrance to Forest Park. It belongs to Toth''s nationwide ''Whispering Giants'' series and is dedicated to Indigenous peoples of the Pioneer Valley.', 'open', 'https://www.atlasobscura.com/places/omiskanoagwiah-springfield-massachusetts', null, 'America/New_York', now()),
  ('Hasbro Gameland', 'hasbro-gameland', 'museums', 42.1045, -72.58742, 'Springfield', 'MA', 'Inside the Springfield History Museum, an interactive exhibit celebrates Milton Bradley and the games later associated with Hasbro. Oversized and playable elements turn board-game history into a hands-on museum stop.', 'limited', 'https://www.atlasobscura.com/places/hasbro-gameland-exhibit', null, 'America/New_York', now()),
  ('Dr. Seuss Museum', 'dr-seuss-museum', 'museums', 42.1045, -72.58742, 'Springfield', 'MA', 'The Amazing World of Dr. Seuss Museum recreates parts of Theodor Geisel''s Springfield childhood and fills galleries with characters and environments from his books. It complements the outdoor sculpture garden with a separate indoor museum experience.', 'limited', 'https://www.atlasobscura.com/places/dr-seuss-museum', null, 'America/New_York', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as massachusetts from public.stops where state = 'MA';
